	local shortcut = button:FindFirstChild('tecla')
		or button:FindFirstChild('keybutton')
		or button:FindFirstChild('key')
		or button.Parent:FindFirstChild('atalhotempoButton')
	
	assert(button:IsA('GuiButton'), 'Coloque este LocalScript dentro do bot�o.')
	
	local HISTORY_SECONDS = 30
	local RECORD_FPS = 30
	local REWIND_SPEED = 1
	
	-- Vazio: usa as anima��es que j� existem no personagem.
	local CUSTOM_WALK_ID = ''
	
	local OWNER = 'VoltarNoTempo'
	local STEP = 1 / RECORD_FPS
	local CAPACITY = math.ceil(HISTORY_SECONDS * RECORD_FPS) + 2
	
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	
	-- cor original + cor enquanto estiver voltando
	local COR_ORIGINAL = button.BackgroundColor3
	local COR_REWIND = Color3.fromRGB(0, 170, 0)
	
	local rewinding, choosing, writing, destroyed = false, false, false, false
	local key, character, humanoid, root, animator
	
	local history, first, count, clock, nextRecord =
		table.create(CAPACITY), 1, 0, 0, 0
	
	local cursor, index, current, saved = 0, 0, nil, nil
	
	local activeTrack, activeId
	local animationCache = {}
	local connections = {}
	local deathConnection
	
	local generation = 0
	local walkId, jumpId, fallId
	
	---------------------------------------------------
	-- CONEX�ES
	---------------------------------------------------
	
	local function connect(signal, callback)
		local connection = signal:Connect(callback)
		table.insert(connections, connection)
		return connection
	end
	
	---------------------------------------------------
	-- BOT�O
	---------------------------------------------------
	
	local function refreshButton()
		button.BackgroundColor3 =
			rewinding and COR_REWIND or COR_ORIGINAL
	end
	
	---------------------------------------------------
	-- TECLA
	---------------------------------------------------
	
	local function label(text)
		if shortcut
			and (
				shortcut:IsA('TextButton')
					or shortcut:IsA('TextBox')
					or shortcut:IsA('TextLabel')
			) then
	
			writing = true
			shortcut.Text = text
			writing = false
		end
	end
	
	local function refreshKey()
		label(key and key.Name or '-')
	end
	
	---------------------------------------------------
	-- HIST�RICO
	---------------------------------------------------
	
	local function physical(i)
		return ((first + i - 2) % CAPACITY) + 1
	end
	
	local function frame(i)
		return history[physical(i)]
	end
	
	local function clearHistory()
		table.clear(history)
		first, count, clock, nextRecord = 1, 0, 0, 0
		current = nil
	end
	
	local function push(value)
		if count < CAPACITY then
			count += 1
			history[physical(count)] = value
		else
			history[first] = value
			first = first % CAPACITY + 1
		end
	end
	
	---------------------------------------------------
	-- ANIMA��ES
	---------------------------------------------------
	
	local function stopVisual()
		if activeTrack then
			activeTrack:Stop(0.1)
		end
	
		activeTrack, activeId = nil, nil
	end
	
	local function clearAnimations()
		stopVisual()
	
		for _, entry in pairs(animationCache) do
			if entry.track then
				entry.track:Destroy()
			end
	
			entry.animation:Destroy()
		end
	
		table.clear(animationCache)
	end
	
	local function animationFrom(folderName)
		local animate = character and character:FindFirstChild('Animate')
		local folder = animate and animate:FindFirstChild(folderName)
		local animation = folder and folder:FindFirstChildWhichIsA('Animation', true)
	
		return animation and animation.AnimationId or nil
	end
	
	local function validId(id)
		return type(id) == 'string'
			and id:match('%d+')
			and not id:match('^rbxassetid://0$')
	end
	
	local function showAnimation(id, speed)
		if not validId(id) or not animator then
			stopVisual()
			return
		end
	
		if activeId == id and activeTrack and activeTrack.IsPlaying then
			activeTrack:AdjustSpeed(speed)
			return
		end
	
		stopVisual()
	
		local entry = animationCache[id]
	
		if not entry then
			local animation = Instance.new('Animation')
			animation.AnimationId = id
	
			local ok, track = pcall(function()
				return animator:LoadAnimation(animation)
			end)
	
			entry = {
				animation = animation,
				track = ok and track or nil
			}
	
			animationCache[id] = entry
	
			if not ok then
				warn('[TEMPO] N�o foi poss�vel carregar anima��o:', id, track)
			end
		end
	
		if not entry.track then
			return
		end
	
		activeId, activeTrack = id, entry.track
	
		activeTrack.Priority = Enum.AnimationPriority.Action4
		activeTrack.Looped = true
		activeTrack:Play(0.1, 1, speed)
	end
	
	local function recordedLocomotion()
		if not animator then
			return nil, 1
		end
	
		local best, weight = nil, -1
	
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			if track.Priority.Value <= Enum.AnimationPriority.Movement.Value
				and track.WeightCurrent > weight
				and track.Animation then
	
				best, weight = track, track.WeightCurrent
			end
		end
	
		if best then
			return best.Animation.AnimationId, math.abs(best.Speed)
		end
	
		return nil, 1
	end
	
	---------------------------------------------------
	-- GRAVAR
	---------------------------------------------------
	
	local function record()
		local id, speed = recordedLocomotion()
	
		push({
			time = clock,
			cf = root.CFrame,
			velocity = root.AssemblyLinearVelocity,
			angular = root.AssemblyAngularVelocity,
			state = humanoid:GetState(),
			grounded = humanoid.FloorMaterial ~= Enum.Material.Air,
			animation = id,
			animationSpeed = speed
		})
	
		while count > 1
			and clock - frame(2).time > HISTORY_SECONDS do
	
			history[first] = nil
			first = first % CAPACITY + 1
			count -= 1
		end
	end
	
	---------------------------------------------------
	-- APLICAR VOLTA
	---------------------------------------------------
	
	local function apply()
		while index > 1 and frame(index).time > cursor do
			index -= 1
		end
	
		local a, b =
			frame(index),
			frame(math.min(index + 1, count))
	
		if not a or not b then
			return
		end
	
		local duration = b.time - a.time
	
		local alpha =
			duration > 0
			and math.clamp(
				(cursor - a.time) / duration,
				0,
				1
			)
			or 0
	
		local selected =
			alpha < 0.5 and a or b
	
		local cf =
			a.cf:Lerp(b.cf, alpha)
	
		root.CFrame = cf
		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
	
		current = current or {}
	
		current.time, current.cf = cursor, cf
	
		current.velocity =
			a.velocity:Lerp(b.velocity, alpha)
	
		current.angular =
			a.angular:Lerp(b.angular, alpha)
	
		current.state, current.grounded =
			selected.state, selected.grounded
	
		current.animation, current.animationSpeed =
			selected.animation, selected.animationSpeed
	
		local distance =
			b.cf.Position - a.cf.Position
	
		local speed =
			duration > 0
			and Vector3.new(
				distance.X,
				0,
				distance.Z
			).Magnitude / duration
			or 0
	
		if cursor <= frame(1).time then
			stopVisual()
			return
		end
	
		if not selected.grounded then
	
			local id =
				selected.state == Enum.HumanoidStateType.Jumping
				and jumpId
				or fallId
	
			showAnimation(id, 1)
	
		elseif speed > 0.5 then
	
			local id =
				CUSTOM_WALK_ID ~= ''
				and CUSTOM_WALK_ID
				or selected.animation
				or walkId
	
			local rhythm =
				selected.animation
				and selected.animationSpeed
				or speed / 16
	
			if CUSTOM_WALK_ID ~= '' then
				rhythm = speed / 16
			end
	
			showAnimation(
				id,
				math.clamp(
					rhythm * REWIND_SPEED,
					0.25,
					2.5
				)
			)
	
		else
			stopVisual()
		end
	end
	
	---------------------------------------------------
	-- PARAR DE VOLTAR
	---------------------------------------------------
	
	local function stop()
		if not rewinding then
			return
		end
	
		rewinding = false
		refreshButton()
	
		stopVisual()
	
		local keep =
			math.clamp(index, 1, count)
	
		for i = count, keep + 1, -1 do
			history[physical(i)] = nil
		end
	
		count, clock, nextRecord =
			keep, cursor, cursor + STEP
	
		if current then
			if current.time > frame(count).time then
				push(current)
			else
				history[physical(count)] = current
			end
		end
	
		if root and root.Parent and saved then
			root.Anchored = saved.anchored
	
			if current and not root.Anchored then
				root.AssemblyLinearVelocity = current.velocity
				root.AssemblyAngularVelocity = current.angular
			end
		end
	
		if humanoid and humanoid.Parent and saved then
			humanoid.AutoRotate = saved.autoRotate
	
			if current and humanoid.Health > 0 then
				humanoid:ChangeState(current.state)
			end
		end
	
		if saved
			and saved.animate
			and saved.animate.Parent then
	
			saved.animate.Enabled =
				saved.animateEnabled
		end
	
		saved, current = nil, nil
	end
	
	---------------------------------------------------
	-- COME�AR A VOLTAR
	---------------------------------------------------
	
	local function start()
		if rewinding
			or not root
			or not root.Parent
			or not humanoid
			or humanoid.Health <= 0 then
	
			return
		end
	
		if humanoid.SeatPart then
			warn('[TEMPO] Saia do assento antes de usar.')
			return
		end
	
		if count < 2 then
			warn('[TEMPO] Ande um pouco para gravar o caminho.')
			return
		end
	
		animator =
			humanoid:FindFirstChildOfClass('Animator')
	
		if not animator then
			warn('[TEMPO] Animator n�o encontrado.')
			return
		end
	
		walkId =
			animationFrom('walk')
			or animationFrom('run')
	
		jumpId, fallId =
			animationFrom('jump'),
			animationFrom('fall')
	
		local animate =
			character:FindFirstChild('Animate')
	
		if not animate
			or not animate:IsA('LocalScript') then
	
			animate = nil
		end
	
		saved = {
			anchored = root.Anchored,
			autoRotate = humanoid.AutoRotate,
			animate = animate,
			animateEnabled = animate and animate.Enabled
		}
	
		if animate then
			animate.Enabled = false
		end
	
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			if track.Priority.Value <= Enum.AnimationPriority.Movement.Value then
				track:Stop(0.1)
			end
		end
	
		cursor, index, current =
			frame(count).time,
			count,
			nil
	
		rewinding = true
	
		refreshButton()
	
		root.Anchored = true
		humanoid.AutoRotate = false
	
		apply()
	end
	
	---------------------------------------------------
	-- PERSONAGEM
	---------------------------------------------------
	
	local function setup(newCharacter)
		generation += 1
	
		local version = generation
	
		stop()
		clearAnimations()
		clearHistory()
	
		if deathConnection then
			deathConnection:Disconnect()
			deathConnection = nil
		end
	
		character, humanoid, root, animator =
			nil, nil, nil, nil
	
		local h =
			newCharacter:WaitForChild('Humanoid', 10)
	
		local r =
			newCharacter:WaitForChild('HumanoidRootPart', 10)
	
		if destroyed
			or version ~= generation
			or player.Character ~= newCharacter
			or not h
			or not r then
	
			return
		end
	
		character, humanoid, root =
			newCharacter, h, r
	
		animator =
			h:FindFirstChildOfClass('Animator')
	
		deathConnection =
			h.Died:Connect(function()
				stop()
				clearHistory()
			end)
	end
	
	connect(player.CharacterAdded, setup)
	
	connect(player.CharacterRemoving, function(old)
		if old ~= character then
			return
		end
	
		generation += 1
	
		stop()
		clearAnimations()
		clearHistory()
	
		if deathConnection then
			deathConnection:Disconnect()
			deathConnection = nil
		end
	
		character, humanoid, root, animator =
			nil, nil, nil, nil
	end)
	
	---------------------------------------------------
	-- SISTEMA DE ATALHO
	---------------------------------------------------
	
	local function teclaValida(code)
		if not code
			or code == Enum.KeyCode.Unknown then
	
			return false
		end
	
		local nome = code.Name
	
		-- somente uma letra ou n�mero
		if #nome ~= 1 then
			return false
		end
	
		local n = string.byte(nome)
	
		return (n >= 48 and n <= 57)
			or (n >= 65 and n <= 90)
	end
	
	local function assign(code)
		if not teclaValida(code) then
			refreshKey()
			return
		end
	
		local owner =
			_G.HPX_Atalhos[code.Name]
	
		choosing = false
	
		-- tecla usada em outro bot�o
		if owner and owner ~= OWNER then
	
			label('USADA')
	
			task.delay(1.2, function()
				if not destroyed
					and not choosing then
	
					refreshKey()
				end
			end)
	
			-- Desfoca mesmo se a tecla estiver ocupada.
			if shortcut and shortcut:IsA('TextBox') and shortcut:IsFocused() then
				shortcut:ReleaseFocus()
			end
			return
		end
	
		stop()
	
		-- libera tecla antiga
		if key
			and _G.HPX_Atalhos[key.Name] == OWNER then
	
			_G.HPX_Atalhos[key.Name] = nil
		end
	
		key = code
	
		_G.HPX_Atalhos[key.Name] = OWNER
	
		refreshKey()
	
		-- Mesmo comportamento do botao Correr: salvou, sai do TextBox.
		if shortcut and shortcut:IsA('TextBox') and shortcut:IsFocused() then
			shortcut:ReleaseFocus()
		end
	end
	
	---------------------------------------------------
	-- CAMPO DA TECLA
	---------------------------------------------------
	
	if shortcut and shortcut:IsA('TextButton') then
	
		connect(shortcut.Activated, function()
			stop()
			choosing = true
			label('...')
		end)
	
	elseif shortcut and shortcut:IsA('TextBox') then
	
		shortcut.TextEditable = true
		shortcut.ClearTextOnFocus = false
	
		-- Ao clicar, prepara o campo para uma nova letra imediatamente.
		connect(shortcut.Focused, function()
			stop()
			choosing = true
			writing = true
			shortcut.Text = ''
			writing = false
		end)
	
		-- N�O DEIXA DIGITAR MAIS DE UMA TECLA
		connect(
			shortcut:GetPropertyChangedSignal('Text'),
			function()
	
				if writing then
					return
				end
	
				local texto =
					string.upper(shortcut.Text or '')
	
				local primeiro =
					texto:sub(1, 1)
	
				writing = true
				shortcut.Text = primeiro
				writing = false
	
				if primeiro == '' then
					return
				end
	
				local n =
					string.byte(primeiro)
	
				-- apenas A-Z e 0-9
				if not (
					(n >= 48 and n <= 57)
						or
						(n >= 65 and n <= 90)
					) then
	
					writing = true
					shortcut.Text = ''
					writing = false
	
					return
				end
	
				local code =
					Enum.KeyCode[primeiro]
	
				if code then
					assign(code)
				end
			end
		)
	
		connect(shortcut.FocusLost, function()
			choosing = false
			if not writing then
				refreshKey()
			end
		end)
	
	else
	
		warn(
			'[TEMPO] Falta TextButton ou TextBox chamado tecla.'
		)
	
	end
	
	---------------------------------------------------
	-- SEGURAR BOT�O = VOLTAR
	---------------------------------------------------
	
	connect(button.InputBegan, function(input)
	
		-- Clicar no campo do atalho nao inicia o rewind.
		if shortcut and shortcut:IsA('GuiObject') and shortcut.Visible then
			local pos, size = shortcut.AbsolutePosition, shortcut.AbsoluteSize
			local mouse = input.Position
			if mouse.X >= pos.X and mouse.X <= pos.X + size.X
				and mouse.Y >= pos.Y and mouse.Y <= pos.Y + size.Y then
				return
			end
		end
	
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
	
			start()
		end
	end)
	
	---------------------------------------------------
	-- SOLTAR BOT�O = PARAR
	---------------------------------------------------
	
	connect(button.InputEnded, function(input)
	
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
	
			stop()
		end
	end)
	
	---------------------------------------------------
	-- SEGURAR TECLA = VOLTAR
	---------------------------------------------------
	
	connect(UIS.InputBegan, function(input, processed)
	
		if input.UserInputType ~= Enum.UserInputType.Keyboard then
			return
		end
	
		if choosing then
			if not UIS:GetFocusedTextBox() then
				assign(input.KeyCode)
			end
	
			return
		end
	
		if not processed
			and not UIS:GetFocusedTextBox()
			and key == input.KeyCode then
	
			start()
		end
	end)
	
	---------------------------------------------------
	-- SOLTAR TECLA = PARAR
	---------------------------------------------------
	
	connect(UIS.InputEnded, function(input)
	
		if input.UserInputType == Enum.UserInputType.Keyboard
			and key == input.KeyCode then
	
			stop()
		end
	end)
	
	connect(UIS.WindowFocusReleased, stop)
	connect(UIS.TextBoxFocused, stop)
	
	---------------------------------------------------
	-- VOLTAR NO TEMPO
	---------------------------------------------------
	
	connect(RunService.PreSimulation, function(dt)
	
		if not rewinding then
			return
		end
	
		if not root
			or not root.Parent
			or humanoid.Health <= 0 then
	
			stop()
			return
		end
	
		cursor =
			math.max(
				frame(1).time,
				cursor - dt * REWIND_SPEED
			)
	
		apply()
	end)
	
	---------------------------------------------------
	-- GRAVA��O AUTOM�TICA
	---------------------------------------------------
	
	connect(RunService.PostSimulation, function(dt)
	
		-- agora n�o precisa clicar para ativar a grava��o
		if rewinding
			or not root
			or not root.Parent
			or humanoid.Health <= 0 then
	
			return
		end
	
		clock += dt
	
		if clock >= nextRecord then
			nextRecord = clock + STEP
			record()
		end
	end)
	
	---------------------------------------------------
	-- DESTRUIR
	---------------------------------------------------
	
	script.Destroying:Connect(function()
	
		destroyed = true
		generation += 1
	
		stop()
		clearAnimations()
	
		if deathConnection then
			deathConnection:Disconnect()
		end
	
		for _, connection in ipairs(connections) do
			connection:Disconnect()
		end
	
		if key
			and _G.HPX_Atalhos[key.Name] == OWNER then
	
			_G.HPX_Atalhos[key.Name] = nil
		end
	
		table.clear(history)
	end)
	
	---------------------------------------------------
	-- INICIAR
	---------------------------------------------------
	
	refreshKey()
	refreshButton()
	
	if player.Character then
		task.spawn(setup, player.Character)
	end
end
local function ZHXPTI_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.movi.ScrollingFrame.femotesButton.LocalScript
    local script = Instance.new("LocalScript")
