			return nil
		end
	
		local charCode =
			string.byte(keyName)
	
		-- Somente A-Z e 0-9
		if not (
			(charCode >= 48 and charCode <= 57)
				or
				(charCode >= 65 and charCode <= 90)
			) then
	
			return nil
		end
	
		return Enum.KeyCode[keyName]
