	-- DEFINIR TECLA
	---------------------------------------------------
	
	local function definirTecla(keyCode)
		if not keyCode
			or keyCode == Enum.KeyCode.Unknown then
	
			return
		end
	
		local nome = keyCode.Name
		local dono = _G.HPX_Atalhos[nome]
	
		---------------------------------------------------
		-- TECLA J� USADA
		---------------------------------------------------
	
		if dono and dono ~= OWNER then
	
			if keyButton then
	
				atualizandoTextoTecla = true
				keyButton.Text = "USADA"
				atualizandoTextoTecla = false
	
			end
	
			task.delay(1.2, function()
				atualizarTextoTecla()
			end)
	
			return
		end
	
		---------------------------------------------------
		-- LIBERA TECLA ANTIGA
		---------------------------------------------------
	
		if teclaAtual
			and _G.HPX_Atalhos[teclaAtual.Name] == OWNER then
	
			_G.HPX_Atalhos[teclaAtual.Name] = nil
		end
	
		---------------------------------------------------
		-- SALVA NOVA TECLA
		---------------------------------------------------
	
		teclaAtual = keyCode
		_G.HPX_Atalhos[nome] = OWNER
	
		atualizarTextoTecla()
	
		if keyButton
			and keyButton:IsA("TextBox")
			and keyButton:IsFocused() then
	
			keyButton:ReleaseFocus()
		end
	end
	
	---------------------------------------------------
	-- COR DO BOT�O
	---------------------------------------------------
	
	local function atualizarBotao()
	
		if antiFlingAtivo then
	
			antiFlingButton.BackgroundColor3 =
				corAtiva
	
		else
	
			antiFlingButton.BackgroundColor3 =
				corOriginal
	
		end
	end
	
	---------------------------------------------------
	-- DESLIGAR COLIS�O
	---------------------------------------------------
	
	local function desligarColisaoDoPersonagem()
	
		local character = player.Character
	
		if not character then
			return
		end
	
		partesColisaoOriginal = {}
	
		for _, part in ipairs(
			character:GetDescendants()
			) do
	
			if part:IsA("BasePart") then
	
				partesColisaoOriginal[part] =
					part.CanCollide
	
				part.CanCollide = false
			end
		end
	end
	
	---------------------------------------------------
	-- RESTAURAR COLIS�O
	---------------------------------------------------
	
	local function restaurarColisaoDoPersonagem()
	
		for part, valor
			in pairs(partesColisaoOriginal) do
	
			if part and part.Parent then
				part.CanCollide = valor
			end
		end
	
		partesColisaoOriginal = {}
	end
	
	---------------------------------------------------
	-- DESLIGAR ANTI FLING
	---------------------------------------------------
	
	local function desligarAntiFling()
	
		if antiFlingConnection then
			antiFlingConnection:Disconnect()
			antiFlingConnection = nil
		end
	
		antiFlingAtivo = false
	
		restaurarColisaoDoPersonagem()
	
		atualizarBotao()
	end
	
	---------------------------------------------------
	-- LIGAR ANTI FLING
	---------------------------------------------------
	
	local function ligarAntiFling()
	
		if flyState
			and flyState.Value then
	
			return
		end
	
		local character =
			player.Character
	
		if not character then
			return
		end
	
		antiFlingAtivo = true
	
		desligarColisaoDoPersonagem()
	
		atualizarBotao()
	
		antiFlingConnection =
			RunService.RenderStepped:Connect(function()
	
				if not antiFlingAtivo
					or not player.Character then
	
					return
				end
	
				for _, part in ipairs(
					player.Character:GetDescendants()
					) do
	
					if part:IsA("BasePart") then
						part.CanCollide = false
					end
				end
			end)
	end
	
	---------------------------------------------------
	-- ALTERNAR
	---------------------------------------------------
	
	local function alternarAntiFling()
	
		if antiFlingAtivo then
			desligarAntiFling()
		else
			ligarAntiFling()
		end
	end
	
	---------------------------------------------------
	-- FLY
	---------------------------------------------------
	
	if flyState then
	
		flyState:GetPropertyChangedSignal("Value"):Connect(function()
	
			if flyState.Value
				and antiFlingAtivo then
	
				desligarAntiFling()
			end
		end)
	end
	
	---------------------------------------------------
	-- CAMPO DA TECLA
	---------------------------------------------------
	
	if keyButton
		and keyButton:IsA("TextBox") then
	
		keyButton.TextEditable = true
		keyButton.ClearTextOnFocus = false
	
		keyButton:GetPropertyChangedSignal("Text"):Connect(function()
	
			if atualizandoTextoTecla then
				return
			end
	
			local texto =
				string.upper(
					keyButton.Text or ""
				)
	
			-- SOMENTE 1 CARACTERE
			local primeiroCaractere =
				texto:sub(1, 1)
	
			local tecla =
				obterTecla(
					primeiroCaractere
				)
	
			local textoValido =
				tecla
				and primeiroCaractere
				or ""
	
			atualizandoTextoTecla = true
	
			keyButton.Text =
				textoValido
	
			atualizandoTextoTecla = false
	
			if tecla then
				definirTecla(tecla)
			end
		end)
	
		keyButton.FocusLost:Connect(function()
			atualizarTextoTecla()
		end)
	end
	
	---------------------------------------------------
	-- BOT�O ANTI FLING
	---------------------------------------------------
	
	if antiFlingButton:IsA("TextButton") then
	
		antiFlingButton.MouseButton1Click:Connect(
			alternarAntiFling
		)
	
	else
	
		antiFlingButton.Activated:Connect(
			alternarAntiFling
		)
	
	end
	
	---------------------------------------------------
	-- ATALHO
	---------------------------------------------------
	
	UserInputService.InputBegan:Connect(function(
		input,
		gameProcessed
	)
	
		if gameProcessed then
			return
		end
	
		-- N�o ativa o AntiFling enquanto estiver
		-- digitando no campo da tecla
		if keyButton
			and keyButton:IsA("TextBox")
			and keyButton:IsFocused() then
	
			return
		end
	
		if teclaAtual
			and input.UserInputType
			== Enum.UserInputType.Keyboard
			and input.KeyCode
			== teclaAtual then
	
			alternarAntiFling()
		end
	end)
	
	---------------------------------------------------
	-- RESPAWN
	---------------------------------------------------
	
	player.CharacterAdded:Connect(function()
	
		if antiFlingAtivo then
	
			desligarAntiFling()
	
			task.wait()
	
			ligarAntiFling()
		end
	end)
	
	---------------------------------------------------
	-- LIMPEZA
	---------------------------------------------------
	
	script.Destroying:Connect(function()
	
		if teclaAtual
			and _G.HPX_Atalhos[teclaAtual.Name] == OWNER then
	
			_G.HPX_Atalhos[teclaAtual.Name] = nil
		end
	
		if antiFlingConnection then
			antiFlingConnection:Disconnect()
			antiFlingConnection = nil
		end
	end)
	
	---------------------------------------------------
	-- INICIAR
	---------------------------------------------------
	
	atualizarTextoTecla()
	atualizarBotao()
end
local function VKFWNF_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.movi.ScrollingFrame.RunButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_RunButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	-- HPX CORRER | Interface 100% Scale | LocalScript dentro de RunButton
	-- Mantem FlyAtivo, atalho exclusivo, speedBox e slider.
	local Players = game:GetService('Players')
	local UIS = game:GetService('UserInputService')
	local player = Players.LocalPlayer
	local runButton = script.Parent
	assert(runButton:IsA('GuiButton'), 'O script deve ficar dentro do RunButton (TextButton/ImageButton).')
	
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	local OWNER = 'Correr'
	local MIN_SPEED, MAX_SPEED, DEFAULT_SPEED = -50, 500, 50
	local BASE_WALK_SPEED = 16
	local velocidade = DEFAULT_SPEED
	local correndo, teclaAtual, atualizandoTecla, arrastando = false, nil, false, false
	local corOriginal, corAtiva = runButton.BackgroundColor3, Color3.fromRGB(0,170,0)
	local conexoes = {}
	local function conectar(signal, fn)
		local c = signal:Connect(fn)
		table.insert(conexoes,c)
		return c
	end
	
	local mainFrame = runButton:FindFirstAncestor('mainFrame')
	local flyState
	if mainFrame then
		local stalker = mainFrame:FindFirstChild('stalker')
		local cmds = stalker and stalker:FindFirstChild('Cmds',true)
		if cmds then
			flyState = cmds:FindFirstChild('FlyAtivo')
			if not flyState then
				flyState = Instance.new('BoolValue')
				flyState.Name = 'FlyAtivo'
				flyState.Parent = cmds
			end
		end
	end
	
	-- Remove controles antigos criados por versoes anteriores para evitar sobreposicao.
	for _, obj in ipairs(runButton:GetChildren()) do
		if obj.Name == 'HPX_RunLayout' then obj:Destroy() end
	end
	for _, nome in ipairs({'speed','keybutton','key'}) do
		local antigo = runButton:FindFirstChild(nome)
		if antigo and antigo:IsA('GuiObject') then antigo.Visible = false end
	end
	runButton.Text = ''
	runButton.ClipsDescendants = true
	runButton.AutoButtonColor = false
	
	local function criar(classe, nome, parent, props)
		local obj = Instance.new(classe)
		obj.Name = nome
		for k,v in pairs(props) do obj[k]=v end
		obj.Parent = parent
		return obj
	end
	local function arredondar(obj, pixels)
		criar('UICorner','Corner',obj,{CornerRadius=UDim.new(0,pixels)})
	end
	local function textoResponsivo(obj, maxSize, minSize)
		obj.TextScaled = true
		criar('UITextSizeConstraint','TextLimit',obj,{MinTextSize=minSize,MaxTextSize=maxSize})
	end
	local layout = criar('Frame','HPX_RunLayout',runButton,{
		BackgroundTransparency=1,Size=UDim2.fromScale(1,1),Position=UDim2.fromScale(0,0),
		ClipsDescendants=true,Active=false
	})
	local titulo = criar('TextLabel','Titulo',layout,{
		BackgroundTransparency=1,Position=UDim2.fromScale(.065,.095),Size=UDim2.fromScale(.61,.38),
		Text='Correr',Font=Enum.Font.GothamBold,TextColor3=Color3.new(1,1,1),
		TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Center
	})
	textoResponsivo(titulo,23,8)
	
	local keyBox = criar('TextBox','Atalho',layout,{
		Position=UDim2.fromScale(.755,.12),Size=UDim2.fromScale(.19,.39),
		BackgroundColor3=Color3.fromRGB(34,43,64),BorderSizePixel=0,
		Text='',PlaceholderText='-',PlaceholderColor3=Color3.fromRGB(220,225,235),Font=Enum.Font.GothamBold,TextColor3=Color3.new(1,1,1),
		TextXAlignment=Enum.TextXAlignment.Center,ClearTextOnFocus=false,
		TextEditable=true,ZIndex=3
	})
	arredondar(keyBox,8)
	textoResponsivo(keyBox,17,7)
	
	local track = criar('Frame','Barra',layout,{
		Position=UDim2.fromScale(.075,.695),Size=UDim2.fromScale(.54,.125),
		BackgroundColor3=Color3.fromRGB(34,43,64),BorderSizePixel=0,Active=true,ZIndex=2
	})
	arredondar(track,100)
	local fill = criar('Frame','Preenchimento',track,{
		Position=UDim2.fromScale(0,0),Size=UDim2.fromScale(0,1),
		BackgroundColor3=Color3.fromRGB(0,170,255),BorderSizePixel=0,ZIndex=3
	})
	arredondar(fill,100)
	local knob = criar('Frame','Bolinha',track,{
		AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(0,.5),
		Size=UDim2.fromScale(.115,2.0),BackgroundColor3=Color3.fromRGB(245,247,255),
		BorderSizePixel=0,Active=true,ZIndex=4
	})
	criar('UIAspectRatioConstraint','Circular',knob,{AspectRatio=1,AspectType=Enum.AspectType.FitWithinMaxSize})
	arredondar(knob,100)
	
	local speedBox = criar('TextBox','Valor',layout,{
		Position=UDim2.fromScale(.675,.615),Size=UDim2.fromScale(.27,.285),
		BackgroundColor3=Color3.fromRGB(34,43,64),BorderSizePixel=0,
		Text='50',Font=Enum.Font.GothamBold,TextColor3=Color3.new(1,1,1),
		ClearTextOnFocus=false,TextXAlignment=Enum.TextXAlignment.Center,ZIndex=3
	})
	arredondar(speedBox,8)
	textoResponsivo(speedBox,16,7)
	
	local function humanoid()
		local char = player.Character
		local h = char and char:FindFirstChildOfClass('Humanoid')
		return h and h.Health > 0 and h or nil
	end
	local function walkSpeed()
		return math.max(0,(velocidade-MIN_SPEED)*BASE_WALK_SPEED/(DEFAULT_SPEED-MIN_SPEED))
	end
	local function atualizarVisual()
		runButton.BackgroundColor3 = correndo and corAtiva or corOriginal
	end
	local function atualizarBarra()
		local p = math.clamp((velocidade-MIN_SPEED)/(MAX_SPEED-MIN_SPEED),0,1)
		fill.Size = UDim2.fromScale(p,1)
		knob.Position = UDim2.fromScale(p,.5)
		if not speedBox:IsFocused() then speedBox.Text = tostring(velocidade) end
	end
	local function definirVelocidade(valor)
		if not valor then return end
		velocidade = math.clamp(math.floor(valor+.5),MIN_SPEED,MAX_SPEED)
		atualizarBarra()
		if correndo then
			local h = humanoid()
			if h then h.WalkSpeed = walkSpeed() end
		end
	end
	local function desligar()
		correndo=false
		local h=humanoid()
		if h then h.WalkSpeed=BASE_WALK_SPEED end
		atualizarVisual()
	end
	local function alternar()
		if correndo then desligar(); return end
		if flyState and flyState.Value then return end
		local h=humanoid()
		if not h then return end
		correndo=true
		h.WalkSpeed=walkSpeed()
		atualizarVisual()
	end
	
	local numbers = {'Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine'}
	local function codigo(texto)
		local ch=string.upper(tostring(texto or ''):sub(1,1))
		if ch:match('^[A-Z]$') then return Enum.KeyCode[ch] end
		if ch:match('^%d$') then return Enum.KeyCode[numbers[tonumber(ch)+1]] end
		return nil
	end
	local function exibicao(key)
		if not key then return '' end
		for i,n in ipairs(numbers) do if key.Name == n then return tostring(i-1) end end
		return key.Name
	end
	local function registro()
		if type(_G.HPX_Atalhos) ~= 'table' then _G.HPX_Atalhos = {} end
		return _G.HPX_Atalhos
	end
	-- O tracinho aparece apenas como PlaceholderText quando nao ha tecla.
	local function atualizarTecla()
		atualizandoTecla=true
		keyBox.Text=exibicao(teclaAtual)
		atualizandoTecla=false
	end
	local avisoId=0
	local function definirTecla(key)
		if not key then return end
		local reg=registro()
		local nome=exibicao(key)
		local dono=reg[nome] or reg[key.Name]
		if dono and dono~=OWNER then
			avisoId+=1
			local id=avisoId
			atualizandoTecla=true;keyBox.Text='USADA';atualizandoTecla=false
			task.delay(1.2,function() if id==avisoId and keyBox.Parent then atualizarTecla() end end)
			return
		end
		avisoId+=1
		if teclaAtual then
			local velho=exibicao(teclaAtual)
			if reg[velho]==OWNER then reg[velho]=nil end
			if reg[teclaAtual.Name]==OWNER then reg[teclaAtual.Name]=nil end
		end
		teclaAtual=key
		reg[nome]=OWNER
		atualizarTecla()
		if keyBox:IsFocused() then keyBox:ReleaseFocus() end
	end
	conectar(keyBox:GetPropertyChangedSignal('Text'),function()
		if atualizandoTecla or not keyBox:IsFocused() then return end
		local key=codigo(keyBox.Text)
		if key then definirTecla(key) end
	end)
	conectar(keyBox.FocusLost,atualizarTecla)
	conectar(speedBox.FocusLost,function()
		local value=tonumber(speedBox.Text)
		if value then definirVelocidade(value) else atualizarBarra() end
	end)
	
	local function ajustarPelaTela(x)
		if track.AbsoluteSize.X<=0 then return end
		local p=math.clamp((x-track.AbsolutePosition.X)/track.AbsoluteSize.X,0,1)
		definirVelocidade(MIN_SPEED+(MAX_SPEED-MIN_SPEED)*p)
	end
	for _,gui in ipairs({track,knob}) do
		conectar(gui.InputBegan,function(input)
			if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
				arrastando=true
				ajustarPelaTela(input.Position.X)
			end
		end)
	end
	conectar(UIS.InputChanged,function(input)
		if arrastando and (input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch) then
			ajustarPelaTela(input.Position.X)
		end
	end)
	conectar(UIS.InputEnded,function(input)
		if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
			arrastando=false
		end
	end)
	conectar(runButton.Activated,function()
		if arrastando or keyBox:IsFocused() or speedBox:IsFocused() then return end
		local mouse=UIS:GetMouseLocation()
		-- Nao alternar ao clicar nos campos ou na barra.
		local function dentro(obj)
			local p,s=obj.AbsolutePosition,obj.AbsoluteSize
			return mouse.X>=p.X and mouse.X<=p.X+s.X and mouse.Y>=p.Y and mouse.Y<=p.Y+s.Y
		end
		if dentro(track) or dentro(keyBox) or dentro(speedBox) then return end
		alternar()
	end)
	conectar(UIS.InputBegan,function(input,processed)
		if processed or UIS:GetFocusedTextBox() then return end
		if teclaAtual and input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode==teclaAtual then alternar() end
	end)
	if flyState then
		conectar(flyState:GetPropertyChangedSignal('Value'),function()
			if flyState.Value and correndo then desligar() end
		end)
	end
	conectar(player.CharacterAdded,function()
		if correndo then correndo=false;atualizarVisual() end
	end)
	conectar(script.Destroying,function()
		if correndo then desligar() end
		if teclaAtual then
			local reg=registro()
			if reg[exibicao(teclaAtual)]==OWNER then reg[exibicao(teclaAtual)]=nil end
			if reg[teclaAtual.Name]==OWNER then reg[teclaAtual.Name]=nil end
		end
		for _,c in ipairs(conexoes) do c:Disconnect() end
	end)
	
	atualizarBarra()
	atualizarTecla()
	atualizarVisual()
	print('[HPX CORRER] Scale pronto. Atalho e velocidade configuraveis.')
	
end
