local function HLMLU_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.anima��es.Bolhoso.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_Bolhoso"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local Players = game:GetService("Players")
	
	local player = Players.LocalPlayer
	local button = script.Parent
	
	-- BUBBLY ANIMATION PACKAGE
	-- usando os IDs reais de anima��o e n�o os IDs do cat�logo
	local BUBBLY = {
		Idle1 = "rbxassetid://910004836",
		Idle2 = "rbxassetid://910009958",
	
		Walk = "rbxassetid://910034870",
		Run = "rbxassetid://910025107",
	
		Jump = "rbxassetid://910016857",
		Fall = "rbxassetid://910001910",
	
		Climb = "rbxassetid://909997997",
	
		Swim = "rbxassetid://910028158",
		SwimIdle = "rbxassetid://910030921"
	}
	
	local function setAnim(animObj, id)
		if animObj and id ~= "" then
			animObj.AnimationId = id
		end
	end
	
	local function pararAnimacoes(humanoid)
		for _, track in pairs(humanoid:GetPlayingAnimationTracks()) do
			track:Stop()
		end
	end
	
	local function aplicarAnimacao()
		local character = player.Character or player.CharacterAdded:Wait()
		local humanoid = character:WaitForChild("Humanoid")
		local animate = character:WaitForChild("Animate")
	
		pararAnimacoes(humanoid)
	
		setAnim(animate.idle.Animation1, BUBBLY.Idle1)
		setAnim(animate.idle.Animation2, BUBBLY.Idle2)
	
		setAnim(animate.walk.WalkAnim, BUBBLY.Walk)
		setAnim(animate.run.RunAnim, BUBBLY.Run)
	
		setAnim(animate.jump.JumpAnim, BUBBLY.Jump)
		setAnim(animate.fall.FallAnim, BUBBLY.Fall)
	
		setAnim(animate.climb.ClimbAnim, BUBBLY.Climb)
	
		setAnim(animate.swim.Swim, BUBBLY.Swim)
		setAnim(animate.swimidle.SwimIdle, BUBBLY.SwimIdle)
	
		animate.Disabled = true
		task.wait(0.2)
		animate.Disabled = false
	
		humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
		task.wait(0.1)
		humanoid:ChangeState(Enum.HumanoidStateType.Running)
	end
	
	button.MouseButton1Click:Connect(aplicarAnimacao)
end
