		local KNOWN_VISITS_PER_EXPLORE = 4 -- 4 spawns conhecidos, depois uma arvore
		local spawnOrder,spawnIndex,visitsSinceExplore={},1,0
		local newSpawns=0
	
		local nextScanUntil=0
		local app={Alive=true,Enabled=false,Phase="off",Status="Desligado",Available=0,Attempts=0,Confirmed=0,Earned=0,Observed=0,Unconfirmed=0,Hops=0,Errors=0,Interval=.45,OnChanged=nil}
		local connections,folderConnections,records={},{},{}
		local folder,current,worker,nextHop,lastHop=nil,nil,nil,0,nil
		local generation=0
		local route,routeIndex,routeRefresh={},1,0
		local random=Random.new()
		local held=tonumber(player:GetAttribute("GrimoireHeld"))
		local total=tonumber(player:GetAttribute("GrimoireQuantity"))
		local function disconnect(list)for _,c in ipairs(list)do c:Disconnect()end;table.clear(list)end
		local function notify()if app.OnChanged and app.Alive then pcall(app.OnChanged)end end
		local function status(phase,message)
			if app.Phase==phase and app.Status==message then return end
			app.Phase=phase;app.Status=message;notify()
		end
		local function errorRecord(err)
			app.Errors+=1;app.LastError=tostring(err);status("retry","Tentativa n�o conclu�da � tentando novamente")
		end
		local function connect(signal,fn,bucket)
			local c=signal:Connect(function(...)
				if not app.Alive then return end
				local ok,err=xpcall(fn,debug.traceback,...);if not ok then errorRecord(err)end
			end)
			table.insert(bucket or connections,c);return c
		end
		local function character()
			local c=player.Character
			local h=c and c:FindFirstChildOfClass("Humanoid")
			local r=c and c:FindFirstChild("HumanoidRootPart")
			if c and h and r and h.Health>0 and not r.Anchored and not h.Sit and not h.SeatPart then return c,h,r end
		end
		local function valid(token)return app.Alive and app.Enabled and token==generation end
		local function belongs(o)return folder and folder.Parent and o.Parent==folder end
		local function releasePrompt()
			if current and current.prompt then pcall(function()current.prompt:InputHoldEnd()end);current.prompt=nil end
		end
		local function clearCurrent()releasePrompt();current=nil end
		local function refreshRecord(o,record)
			if not belongs(o)then return end
			local part=o:IsA("BasePart")and o or o:FindFirstChild("Livro",true)
			if not part or not part:IsA("BasePart")then part=o:IsA("Model")and o.PrimaryPart or nil end
			if not part then part=o:FindFirstChildWhichIsA("BasePart",true)end
			record.part=part
			record.prompt=o:FindFirstChildWhichIsA("ProximityPrompt",true)
			record.name=tostring(o:GetAttribute("GrimorioName")or o.Name)
		end
		local function attach(o)
			if records[o]then refreshRecord(o,records[o]);return end
			-- Only direct children of the observed spawn folder are eligible.
			if not belongs(o)or not(o:IsA("Model")or o:IsA("BasePart"))then return end
			local record={connections={},retryAt=0,failures=0};records[o]=record
			refreshRecord(o,record)
			if not o:IsA("BasePart")then
				connect(o.DescendantAdded,function()refreshRecord(o,record)end,record.connections)
				connect(o.DescendantRemoving,function(child)if child==record.part then record.part=nil end end,record.connections)
			end
		end
		local function detach(o)
			local record=records[o];if not record then return end
			disconnect(record.connections);records[o]=nil
			if current and current.object==o then current.removed=true;current.removedAt=now()end
		end
		local function bind(newFolder)
			if newFolder==folder then return end
			clearCurrent();disconnect(folderConnections)
			for o,record in pairs(records)do disconnect(record.connections);records[o]=nil end
			folder=newFolder
			if folder then
				connect(folder.ChildAdded,attach,folderConnections)
				connect(folder.ChildRemoved,detach,folderConnections)
				for _,o in ipairs(folder:GetChildren())do attach(o)end
			end
		end
		for _,pos in ipairs(INITIAL_SPAWNS) do
			knownSpawns[#knownSpawns+1]={pos=pos,name="Conhecido"}
		end
		local function shuffleSpawns()
			spawnOrder={}
			for i=1,#knownSpawns do spawnOrder[i]=i end
			for i=#spawnOrder,2,-1 do
				local j=random:NextInteger(1,i)
				spawnOrder[i],spawnOrder[j]=spawnOrder[j],spawnOrder[i]
			end
			spawnIndex=1
		end
		local function saveSpawn(pos, name)
			for _,saved in ipairs(knownSpawns) do
				if (saved.pos-pos).Magnitude<=3 then return end
			end
			knownSpawns[#knownSpawns+1]={pos=pos,name=name}
			newSpawns+=1
			-- Nova posicao participara da rota na proxima rodada.
			print(string.format("[HPX GRIM NOVO SPAWN] X: %.2f | Y: %.2f | Z: %.2f | Total: %d | %s", pos.X,pos.Y,pos.Z,#knownSpawns,tostring(name)))
			notify()
		end
		local function nearest(root)
			local target,record,best=nil,nil,math.huge;local count=0
			for o,r in pairs(records)do
				if belongs(o)and r.part and r.part.Parent then
					count+=1
					local distance=(r.part.Position-root.Position).Magnitude
					if distance<=SCAN_RADIUS then
						saveSpawn(r.part.Position,r.name)
						if distance<best and now()>=r.retryAt then target,record,best=o,r,distance end
					end
				end
			end
			if app.Available~=count then app.Available=count;notify()end
			return target,record
		end
		local function move(char,root,position)
			if player.Character~=char or not root.Parent then return false end
			-- Translate the character by the root delta, preserving rig pivot offsets.
			char:PivotTo(CFrame.new(position-root.Position)*char:GetPivot())
			root.AssemblyLinearVelocity=Vector3.zero;root.AssemblyAngularVelocity=Vector3.zero
			return true
		end
		local function height(h,r,c)
			local y=h.HipHeight+r.Size.Y*.5+.35
			if h.RigType==Enum.HumanoidRigType.R6 then local leg=c:FindFirstChild("Left Leg");if leg then y+=leg.Size.Y end end
			return math.max(3,y)
		end
		local function shuffle()
			for i=#route,2,-1 do local j=random:NextInteger(1,i);route[i],route[j]=route[j],route[i]end
			routeIndex=1
		end
		-- Rota somente pelas arvores de Workspace.Map.Tree (ordem aleatoria).
		local function buildRoute(token)
			local map=workspace:FindFirstChild("Map")
			local trees=map and map:FindFirstChild(TREE_FOLDER)
			if not trees then routeRefresh=now()+3;status("waiting","Aguardando Workspace.Map.Tree");return false end
			local fresh={}
			for i,tree in ipairs(trees:GetChildren()) do
				if not valid(token) then return false end
				if tree:IsA("Model") or tree:IsA("BasePart") then
					local pos
					if tree:IsA("BasePart") then
						pos=tree.Position-Vector3.new(0,tree.Size.Y/2,0)
					else
						local lowest=math.huge
						for _,part in ipairs(tree:GetDescendants()) do
							if part:IsA("BasePart") then
								local y=part.Position.Y-part.Size.Y/2
								if y<lowest then lowest=y;pos=Vector3.new(part.Position.X,y,part.Position.Z) end
							end
						end
					end
					if pos then fresh[#fresh+1]=pos end
				end
				if i%50==0 then task.wait() end
			end
			if not valid(token) then return false end
			route=fresh;shuffle();routeRefresh=now()+30
			notify()
			return #route>0
		end
		local function exploreTrees(char,hum,root,token)
			if now()<nextHop then return end
			if now()>=routeRefresh or #route==0 then
				if not buildRoute(token) then nextHop=now()+2;return end
			end
			local params=RaycastParams.new()
			params.FilterType=Enum.RaycastFilterType.Exclude
			params.FilterDescendantsInstances={char,workspace:FindFirstChild(FOLDER)}
			params.IgnoreWater=false
			for _=1,math.min(#route,12) do
				if routeIndex>#route then shuffle() end
				local base=route[routeIndex];routeIndex+=1
				local offsets={Vector3.new(TREE_DISTANCE,0,0),Vector3.new(-TREE_DISTANCE,0,0),Vector3.new(0,0,TREE_DISTANCE),Vector3.new(0,0,-TREE_DISTANCE)}
				for _,offset in ipairs(offsets) do
					local origin=base+offset+Vector3.new(0,40,0)
					local hit=workspace:Raycast(origin,Vector3.new(0,-100,0),params)
					if hit and hit.Normal.Y>.65 and hit.Material~=Enum.Material.Water then
						local destination=hit.Position+Vector3.new(0,height(hum,root,char),0)
						if valid(token) and move(char,root,destination) then
							app.Hops+=1
							nextScanUntil=now()+SCAN_SECONDS
							nextHop=now()+math.max(SCAN_SECONDS,app.Interval)
							status("explore",string.format("Arvore %d/%d � analisando rapidamente",routeIndex-1,#route))
							notify()
							return
						end
					end
				end
			end
			nextHop=now()+1
			status("waiting","Procurando chao ao lado das arvores")
		end
		-- Explorar areas igual ao Candy: visitar spawns e pontos laterais aleatorios.
		-- Nunca depende da pasta Tree para continuar a rota.
		local RAIO_EXTRA=120
		local visitasLaterais=0
		local pontoBase=nil
		local function explore(char,hum,root,token)
			if now()<nextHop then return end
			local pos
			if pontoBase and visitasLaterais<1 then
				visitasLaterais+=1
				local ang=random:NextNumber(0,math.pi*2)
				pos=pontoBase+Vector3.new(math.cos(ang)*RAIO_EXTRA,0,math.sin(ang)*RAIO_EXTRA)
			else
				if spawnIndex>#spawnOrder or #spawnOrder==0 then shuffleSpawns() end
				local idx=spawnOrder[spawnIndex]
				if not idx then nextHop=now()+1;return end
				spawnIndex+=1
				local info=knownSpawns[idx]
				if not info then return end
				pontoBase=info.pos
				visitasLaterais=0
				pos=info.pos
			end
			local params=RaycastParams.new()
			params.FilterType=Enum.RaycastFilterType.Exclude
			local excluded={char}
			if folder then table.insert(excluded,folder) end
			params.FilterDescendantsInstances=excluded
			params.IgnoreWater=false
			local hit=workspace:Raycast(pos+Vector3.new(0,55,0),Vector3.new(0,-130,0),params)
			local destination
			if hit and hit.Normal.Y>0.55 and hit.Material~=Enum.Material.Water then
				destination=hit.Position+Vector3.new(0,height(hum,root,char),0)
			else
				destination=pos+Vector3.new(0,3,0)
			end
			if valid(token) and move(char,root,destination) then
				app.Hops+=1
				nextScanUntil=now()+SCAN_SECONDS
				nextHop=now()+SCAN_SECONDS
				status("explore",string.format("Varrendo area %d/%d",spawnIndex-1,#spawnOrder))
				if app.Hops%10==1 then print("[HPX GRIM] Explorando area",app.Hops,"posicao",destination) end
				notify()
			end
		end
		local function begin(o,record,char,hum,root)
			app.Attempts+=1
			current={object=o,record=record,character=char,token=generation,started=now(),deadline=now()+4,moves=0,nextMove=0,lastPosition=record.part.Position}
			status("collect","Coletando "..record.name);notify()
		end
		local function collect(char,root)
			local c=current;if not c then return end
			if not valid(c.token)or c.character~=char then clearCurrent();return end
			local gone=c.removed or not belongs(c.object)
			if gone then
				if not c.removedAt then c.removedAt=now()end
				if not c.confirmed and now()-c.removedAt<.8 then status("confirming","Aguardando atualiza��o do saldo");return end
				-- Observed removal is kept separate from a server inventory grant.
				if c.confirmed then app.LastCollected=c.record.name;status("collected","Coleta confirmada pelo progresso do jogo")
				elseif now()-c.started<=5 and(root.Position-c.lastPosition).Magnitude<12 then app.Observed+=1;app.LastCollected=c.record.name;status("observed","Item removido � aguardando confirma��o do saldo")
				else status("waiting","Grim�rio saiu da regi�o carregada")end
				clearCurrent();nextHop=now()+.4;notify();return
			end
			local part=c.record.part
			if not part or not part.Parent then clearCurrent();return end
			c.lastPosition=part.Position
			if c.confirmed then
				if now()-c.confirmedAt>.8 then c.record.retryAt=now()+3;clearCurrent();status("collected","Coleta confirmada pelo jogo");notify()end
				return
			end
			if now()>=c.deadline then
				c.record.failures+=1;c.record.retryAt=now()+math.min(30,4*2^math.min(3,c.record.failures-1))
				app.Unconfirmed+=1;clearCurrent();status("retry","Sem confirma��o � procurando outro grim�rio");notify();return
			end
			if c.prompt and now()>=c.releaseAt then releasePrompt()end
			if now()>=c.nextMove and c.moves<3 then
				local offsets={Vector3.new(0,.5,0),Vector3.new(1,.5,0),Vector3.new(-1,.5,0)}
				c.moves+=1;c.nextMove=now()+1.1
				if move(char,root,part.Position+offsets[c.moves])then c.lastMove=now()end
				local prompt=c.record.prompt
				if prompt and prompt.Parent and prompt.Enabled and not c.prompt then
					local ok=pcall(function()prompt:InputHoldBegin()end)
					if ok then c.prompt=prompt;c.releaseAt=now()+math.clamp(prompt.HoldDuration+.15,.15,3.5)end
				end
			end
		end
		function app.Step()
			if not app.Alive or not app.Enabled then return end
			local actual=workspace:FindFirstChild(FOLDER)
			if actual~=folder then bind(actual) end
			local char,hum,root=character()
			if not char then clearCurrent();status("waiting","Aguardando personagem");return end
			if current then collect(char,root);return end
			if now()<nextScanUntil then nearest(root);return end
			local o,r=nearest(root)
			if o then begin(o,r,char,hum,root);collect(char,root)
			else explore(char,hum,root,generation) end
		end
		function app.SetEnabled(on)
			if not app.Alive or type(on)~="boolean" then return false end
			generation+=1;app.Enabled=on;clearCurrent();nextHop=0;nextScanUntil=0;visitsSinceExplore=0
			if on then shuffleSpawns();status("waiting","Procurando grimorios")
			else status("off","Desligado") end
			notify();return true
		end
		function app.Report()
			return {enabled=app.Enabled,confirmed=app.Confirmed,available=app.Available,hops=app.Hops,attempts=app.Attempts,status=app.Status}
		end
		function app.Shutdown()
			if not app.Alive then return end
			app.SetEnabled(false);app.Alive=false;disconnect(connections);disconnect(folderConnections)
			for o,r in pairs(records) do disconnect(r.connections);records[o]=nil end
			if worker and worker~=coroutine.running()then pcall(task.cancel,worker)end
			worker=nil;app.OnChanged=nil
		end
		connect(player.CharacterRemoving,function()generation+=1;clearCurrent()end)
		connect(player.CharacterAdded,function()generation+=1;clearCurrent();nextHop=now()+1 end)
		connect(workspace.ChildAdded,function(o)if o.Name==FOLDER then bind(o)end end)
		connect(workspace.ChildRemoved,function(o)if o==folder then bind(nil)end end)
		connect(player:GetAttributeChangedSignal("GrimoireHeld"),function()
			local value=tonumber(player:GetAttribute("GrimoireHeld"));local before=held;held=value
			if value and before and value>before and current and valid(current.token)and not current.confirmed then
				local char,_,root=character()
				if char==current.character and root and(root.Position-current.lastPosition).Magnitude<12 then
					current.confirmed=true;current.confirmedAt=now();app.Confirmed+=1;app.Earned+=value-before
					app.LastCollected=current.record.name;status("collected","Coleta confirmada");notify()
				end
			end
		end)
		bind(workspace:FindFirstChild(FOLDER))
		worker=task.spawn(function()
			while app.Alive do
				if app.Enabled then
					local ok,err=xpcall(app.Step,debug.traceback)
					if not ok then clearCurrent();errorRecord(err);nextHop=now()+3 end
				end
				task.wait(app.Enabled and .18 or .6)
			end
		end)
		return app
	end
	
	-- Interface existente: voxUp > RoVibes > GrimoryButton
	local Players=game:GetService("Players")
	local UIS=game:GetService("UserInputService")
	local player=Players.LocalPlayer
	local gui=player:WaitForChild("PlayerGui")
	local button=script.Parent
	if not button:IsA("GuiButton") or button.Name~="GrimoryButton" then
		warn("[HPX GRIM] Coloque este LocalScript dentro do GrimoryButton")
		return
	end
	if type(_G.HPX_GrimParar)=="function" then pcall(_G.HPX_GrimParar) end
	-- Remove o painel antigo, se estiver presente.
	local antigo=gui:FindFirstChild("RoVibesAutoGrimorios")
	if antigo then
		local controle=antigo:FindFirstChild("Control")
		if controle and controle:IsA("BindableFunction") then
			pcall(function() controle:Invoke("shutdown") end)
		end
		if antigo.Parent then antigo:Destroy() end
	end
	local core=createCore({})
	local active=true
	local links={}
	local OWNER="Grimorio"
	local registry=_G.HPX_Atalhos
	if type(registry)~="table" and typeof(registry)~="Instance" then registry={};_G.HPX_Atalhos=registry end
	local original=button.BackgroundColor3
	local GREEN=Color3.fromRGB(0,170,0)
	local keyField=button:FindFirstChild("keybutton",true) or button:FindFirstChild("keybuton",true) or button:FindFirstChild("key",true) or button:FindFirstChild("tecla",true)
	if keyField and not (keyField:IsA("TextBox") or keyField:IsA("TextButton")) then
		keyField=keyField:FindFirstChildWhichIsA("TextBox",true) or keyField:FindFirstChildWhichIsA("TextButton",true)
	end
	local keyCode=nil
	local choosing=false
	local changing=false
	local warningSeq=0
	local numbers={"Zero","One","Two","Three","Four","Five","Six","Seven","Eight","Nine"}
	local function visible(key)
		if not key then return "-" end
		for i,name in ipairs(numbers) do if key.Name==name then return tostring(i-1) end end
		return key.Name
	end
	local function keyFromText(txt)
		local c=string.upper(tostring(txt or ""):sub(1,1))
		if c:match("^[A-Z]$") then return Enum.KeyCode[c] end
		if c:match("^%d$") then return Enum.KeyCode[numbers[tonumber(c)+1]] end
		return nil
	end
	local function keyText(value)
		if keyField then changing=true;keyField.Text=value;changing=false end
	end
	local function refresh()
		if button.Parent then button.BackgroundColor3=core.Enabled and GREEN or original end
	end
	local function refreshKey() keyText(visible(keyCode)) end
	local function readOwner(name)
		local reg=_G.HPX_Atalhos
		if typeof(reg)=="Instance" then
			local v=reg:FindFirstChild(name)
			return v and v:IsA("StringValue") and v.Value or nil
		elseif type(reg)=="table" then
			local v=reg[name]
			return typeof(v)=="Instance" and v:IsA("StringValue") and v.Value or v
		end
	end
	local function writeOwner(name,owner)
		local reg=_G.HPX_Atalhos
		if typeof(reg)=="Instance" then
			local v=reg:FindFirstChild(name)
			if owner then
				if not v then v=Instance.new("StringValue");v.Name=name;v.Parent=reg end
				if v:IsA("StringValue") then v.Value=owner end
			elseif v and v:IsA("StringValue") and v.Value==OWNER then v:Destroy() end
		elseif type(reg)=="table" then
			if owner or reg[name]==OWNER then reg[name]=owner end
		end
	end
	local function assign(key)
		if not key or key==Enum.KeyCode.Unknown then refreshKey();return end
		local name=visible(key)
		local owner=readOwner(name) or readOwner(key.Name)
		if owner and owner~="" and owner~=OWNER then
			warningSeq+=1;local seq=warningSeq
			keyText("USADA")
			task.delay(1.2,function()if active and seq==warningSeq then refreshKey()end end)
			return
		end
		warningSeq+=1
		if keyCode then
			writeOwner(visible(keyCode),nil)
			if visible(keyCode)~=keyCode.Name then writeOwner(keyCode.Name,nil) end
		end
		keyCode=key
		writeOwner(name,OWNER)
		refreshKey()
		if keyField and keyField:IsA("TextBox") and keyField:IsFocused() then keyField:ReleaseFocus() end
	end
	local function toggle()
		if not active then return end
		core.SetEnabled(not core.Enabled)
		refresh()
		print("[HPX GRIM] "..(core.Enabled and "ATIVADO" or "DESATIVADO"))
	end
	local function link(signal,fn)links[#links+1]=signal:Connect(fn)end
	if keyField and keyField:IsA("TextBox") then
		keyField.TextEditable=true
		keyField.ClearTextOnFocus=false
		local initial=keyFromText(keyField.Text)
		if initial then assign(initial) end
		link(keyField:GetPropertyChangedSignal("Text"),function()
			if changing then return end
			local first=string.upper(keyField.Text or ""):sub(1,1)
			local key=keyFromText(first)
			changing=true;keyField.Text=key and first or "";changing=false
			if key then assign(key) end
		end)
		link(keyField.FocusLost,refreshKey)
	elseif keyField and keyField:IsA("TextButton") then
		local initial=keyFromText(keyField.Text)
		if initial then assign(initial) end
		link(keyField.Activated,function()choosing=true;keyText("...")end)
	else
		warn("[HPX GRIM] keybutton deve ser TextBox ou TextButton")
	end
	link(button.Activated,function()
		if choosing then return end
		-- Evita toggle quando o clique foi no campo de tecla dentro do botao.
		local cursor=UIS:GetMouseLocation()
		if keyField and keyField:IsA("GuiObject") then
			local pos,size=keyField.AbsolutePosition,keyField.AbsoluteSize
			if cursor.X>=pos.X and cursor.X<=pos.X+size.X and cursor.Y>=pos.Y and cursor.Y<=pos.Y+size.Y then return end
		end
		toggle()
	end)
	link(UIS.InputBegan,function(input,processed)
		if not active or input.UserInputType~=Enum.UserInputType.Keyboard then return end
		if choosing then
			choosing=false
			assign(keyFromText(visible(input.KeyCode)))
			return
		end
		if processed or UIS:GetFocusedTextBox() then return end
		if keyCode and input.KeyCode==keyCode then toggle() end
	end)
	local function shutdown()
		if not active then return end
		active=false
		core.Shutdown()
		if keyCode then writeOwner(visible(keyCode),nil);if visible(keyCode)~=keyCode.Name then writeOwner(keyCode.Name,nil) end end
		button.BackgroundColor3=original
		for _,c in ipairs(links)do c:Disconnect()end
	end
	_G.HPX_GrimParar=shutdown
	link(button.Destroying,shutdown)
	refreshKey()
	refresh()
	print("[HPX GRIM] Pronto: GrimoryButton + atalho configuravel, sem painel extra.")
	
end
