		{213.64, 10.92, 731.36}, {-415.35, 16.27, 692.61},
		{284.51, 6.32, -217.77},
	}
	
	-- Remove duplicatas por proximidade (mantem a lista enxuta).
	do
		local unicos = {}
		for _, v in ipairs(coordenadas) do
			local pos = Vector3.new(v[1], v[2], v[3])
			local repetido = false
			for _, ja in ipairs(unicos) do
				if (ja - pos).Magnitude <= RAIO_MESMO_SPAWN then
					repetido = true
					break
				end
			end
			if not repetido then
				table.insert(unicos, pos)
			end
		end
		pontos = unicos
	end
	
	local ativo, rodando, vivo = false, false, true
	local monitorada, conexaoPasta = nil, nil
	
	local function logImportante(mensagem)
		local canal = playerGui:FindFirstChild("HPX_CandySpawnEvento")
		if canal and canal:IsA("BindableEvent") then
			canal:Fire(mensagem)
		end
	end
	
	-- ------------------------------------------------------------------
	-- Deteccao
	-- ------------------------------------------------------------------
	local function pastaCandy()
		return workspace:FindFirstChild(NOME_PASTA)
	end
	
	local function ehDoce(obj)
		return obj and obj.Name:lower() == NOME_DOCE
	end
	
	local function posicaoDoce(obj)
		if obj:IsA("BasePart") then return obj.Position end
		if obj:IsA("Model") then
			local p = obj:FindFirstChildWhichIsA("BasePart", true)
			return p and p.Position or nil
		end
		local p = obj:FindFirstChildWhichIsA("BasePart", true)
		return p and p.Position or nil
	end
	
	local function ignorados()
		local lista = {}
		if player.Character then table.insert(lista, player.Character) end
		local pasta = pastaCandy()
		if pasta then table.insert(lista, pasta) end
		return lista
	end
	
	-- Filtro de subsolo: ignora doces cobertos por chao/peca solida.
	local function doceAcessivel(pos)
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = ignorados()
		params.IgnoreWater = true
	
		local origem = pos + Vector3.new(0, ALTURA_RAYCAST, 0)
		local resultado = workspace:Raycast(origem, Vector3.new(0, -ALTURA_RAYCAST, 0), params)
		-- Se bater no chao ANTES da altura do doce, o doce esta enterrado.
		if resultado and resultado.Position.Y > pos.Y + MARGEM_SUBSOLO then
			return false
		end
		return true
	end
	
	local function adicionarPonto(pos)
		for _, ponto in ipairs(pontos) do
			if (ponto - pos).Magnitude <= RAIO_MESMO_SPAWN then
				return false
			end
		end
		table.insert(pontos, pos)
		return true
	end
	
	local function conectarPasta()
		local pasta = pastaCandy()
		if pasta == monitorada then return end
		if conexaoPasta then conexaoPasta:Disconnect() end
		monitorada = pasta
		conexaoPasta = nil
		if pasta then
			conexaoPasta = pasta.DescendantAdded:Connect(function() end)
		end
	end
	
	-- Todos os doces carregados, sem limite artificial de distancia.
	local function varrerDoces()
		conectarPasta()
		local pasta = pastaCandy()
		local doces = {}
		if not pasta then return doces end
		for _, obj in ipairs(pasta:GetDescendants()) do
			if ehDoce(obj) then
				local pos = posicaoDoce(obj)
				if pos and doceAcessivel(pos)
					and (not tentativasFalhas[obj] or os.clock() >= tentativasFalhas[obj]) then
					table.insert(doces, {obj = obj, pos = pos})
				end
			end
		end
		return doces
	end
	
	-- ------------------------------------------------------------------
	-- Movimento
	-- ------------------------------------------------------------------
	local function personagem()
		local char = player.Character
		if not char then return nil end
		local root = char:FindFirstChild("HumanoidRootPart")
		local hum = char:FindFirstChildWhichIsA("Humanoid")
		if not root or not hum or hum.Health <= 0 then return nil end
		return char, hum, root
	end
	
	local function altura(hum, root, char)
		local y = hum.HipHeight + root.Size.Y * 0.5 + 0.35
		if hum.RigType == Enum.HumanoidRigType.R6 then
			local leg = char:FindFirstChild("Left Leg")
			if leg then y += leg.Size.Y end
		end
		return math.max(3, y)
	end
	
	-- Desloca o personagem preservando o offset do rig (metodo do candy.lua).
	local function mover(char, root, position)
		if player.Character ~= char or not root.Parent then
			return false
		end
		char:PivotTo(CFrame.new(position - root.Position) * char:GetPivot())
		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
		return true
	end
	
	local function teleportar(pos)
		if not ativo or not vivo then return false end
		local char, hum, root = personagem()
		if not char then return false end
		return mover(char, root, pos)
	end
	
	local function chaoProximo(pos)
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = ignorados()
		params.IgnoreWater = true
	
		local result = workspace:Raycast(pos + Vector3.new(0, 32, 0), Vector3.new(0, -90, 0), params)
		if result then return result.Position + Vector3.new(0, ALTURA_PONTO, 0) end
		return pos + Vector3.new(0, ALTURA_PONTO, 0)
	end
	
	-- ------------------------------------------------------------------
	-- Exploracao por arvores (Workspace.Map.Tree)
	-- ------------------------------------------------------------------
	local function embaralhar(lista)
		for i = #lista, 2, -1 do
			local j = random:NextInteger(1, i)
			lista[i], lista[j] = lista[j], lista[i]
		end
	end
	
	local function construirRotaArvores()
		rotaArvores = {}
		rotaIndex = 1
	
		local mapa = workspace:FindFirstChild("Map")
		local arvores = mapa and mapa:FindFirstChild(TREE_FOLDER)
		if not arvores then
			rotaRefresh = os.clock() + 3
			return false
		end
	
		local novas = {}
		for i, arvore in ipairs(arvores:GetChildren()) do
			if arvore:IsA("Model") or arvore:IsA("BasePart") then
				local pos
				if arvore:IsA("BasePart") then
					pos = arvore.Position - Vector3.new(0, arvore.Size.Y / 2, 0)
				else
					local maisBaixo = math.huge
					for _, parte in ipairs(arvore:GetDescendants()) do
						if parte:IsA("BasePart") then
							local y = parte.Position.Y - parte.Size.Y / 2
							if y < maisBaixo then
								maisBaixo = y
								pos = Vector3.new(parte.Position.X, y, parte.Position.Z)
							end
						end
					end
				end
				if pos then table.insert(novas, pos) end
			end
			if i % 50 == 0 then task.wait() end
		end
	
		rotaArvores = novas
		embaralhar(rotaArvores)
		rotaRefresh = os.clock() + REFRESH_ROTA
		return #rotaArvores > 0
	end
	
	-- Teleporta para o chao ao lado de uma arvore.
	local function explorarArvore()
		local char, hum, root = personagem()
		if not char then return false end
	
		if os.clock() >= rotaRefresh or #rotaArvores == 0 then
			if not construirRotaArvores() then return false end
		end
	
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
	
		local exclusoes = {char}
		local pasta = pastaCandy()
		if pasta then table.insert(exclusoes, pasta) end
		params.FilterDescendantsInstances = exclusoes
		params.IgnoreWater = false
	
		for _ = 1, math.min(#rotaArvores, 12) do
			if rotaIndex > #rotaArvores then
				embaralhar(rotaArvores)
				rotaIndex = 1
			end
	
			local base = rotaArvores[rotaIndex]
			rotaIndex = rotaIndex + 1
	
			local offsets = {
				Vector3.new(TREE_DISTANCE, 0, 0),
				Vector3.new(-TREE_DISTANCE, 0, 0),
				Vector3.new(0, 0, TREE_DISTANCE),
				Vector3.new(0, 0, -TREE_DISTANCE),
			}
	
			for _, offset in ipairs(offsets) do
				local origem = base + offset + Vector3.new(0, 40, 0)
				local hit = workspace:Raycast(origem, Vector3.new(0, -100, 0), params)
				if hit and hit.Normal.Y > 0.65 and hit.Material ~= Enum.Material.Water then
					local destino = hit.Position + Vector3.new(0, altura(hum, root, char), 0)
					if mover(char, root, destino) then
						return true
					end
				end
			end
		end
	
		return false
	end
	
	-- ------------------------------------------------------------------
	-- Coleta
	-- ------------------------------------------------------------------
	local function coletar(doce)
		if not ativo or not vivo or not doce.obj or not doce.obj.Parent then return false end
		local posInicial = doce.pos
		if not posInicial or not doceAcessivel(posInicial) then return false end
	
		local inicio = os.clock()
		local pasta = pastaCandy()
	
		while vivo and ativo and doce.obj.Parent and pasta
			and doce.obj:IsDescendantOf(pasta)
			and os.clock() - inicio < TEMPO_TENTATIVA do
			local pos = posicaoDoce(doce.obj)
			if not pos or not doceAcessivel(pos) then break end
			if not teleportar(pos + Vector3.new(0, 1.6, 0)) then break end
			task.wait(INTERVALO_TENTATIVA)
		end
	
		-- Somente considera coletado se o Candy saiu da pasta.
		local coletado = not doce.obj.Parent or not (pasta and doce.obj:IsDescendantOf(pasta))
	
		if coletado and adicionarPonto(posInicial) then
			logImportante(string.format(
				"[HPX CANDY NOVO SPAWN] X: %.2f | Y: %.2f | Z: %.2f | Total: %d",
				posInicial.X, posInicial.Y, posInicial.Z, #pontos
				))
		end
		if not coletado then
			tentativasFalhas[doce.obj] = os.clock() + PAUSA_DOCE_FALHOU
		end
		return coletado
	end
	
	-- Doces visiveis tem prioridade sobre a rota de exploracao.
	local function tentarDocesDisponiveis()
		local doces = varrerDoces()
		if #doces == 0 then return false end
	
		local _, _, root = personagem()
		if not root then return false end
	
		table.sort(doces, function(a, b)
			return (a.pos - root.Position).Magnitude < (b.pos - root.Position).Magnitude
		end)
	
		for _, info in ipairs(doces) do
			if not ativo or not vivo then return true end
			local pasta = pastaCandy()
			if pasta and info.obj.Parent and info.obj:IsDescendantOf(pasta) and doceAcessivel(info.pos) then
				coletar(info)
			end
		end
		return true
	end
	
	-- ------------------------------------------------------------------
	-- Loop principal
	-- ------------------------------------------------------------------
	local function rodada()
		if rodando then return end
		rodando = true
		task.spawn(function()
			while vivo and ativo do
				-- Primeiro percorre todos os CandyTemplate ja detectados.
				if tentarDocesDisponiveis() then
					task.wait(0.08)
				else
					-- Sem doces carregados: visita pontos conhecidos/arvores e re checa.
					local rota = table.clone(pontos)
					embaralhar(rota)
	
					for _, ponto in ipairs(rota) do
						if not vivo or not ativo then break end
						if #varrerDoces() > 0 then break end
	
						-- A cada N spawns conhecidos, explora uma arvore.
						if visitasConhecidas >= VISITAS_CONHECIDAS_ANTES_ARVORE then
							visitasConhecidas = 0
							if explorarArvore() then
								task.wait(ESPERA_CARREGAR)
								if #varrerDoces() > 0 then break end
							end
						else
							visitasConhecidas = visitasConhecidas + 1
						end
	
						-- Aproximar-se faz o cliente poder receber objetos daquela regiao.
						teleportar(chaoProximo(ponto))
						task.wait(ESPERA_CARREGAR)
						if #varrerDoces() > 0 then break end
	
						-- Explora arredores alternados para cobrir mais regioes
						-- onde o jogo cria os doces de acordo com a posicao do jogador.
						for visita = 1, VISITAS_EXTRAS_POR_PONTO do
							if not vivo or not ativo then break end
							local angulo = random:NextNumber() * math.pi * 2
							local deslocamento = Vector3.new(
								math.cos(angulo) * RAIO_ANALISE_EXTRA,
								0,
								math.sin(angulo) * RAIO_ANALISE_EXTRA
							)
							teleportar(chaoProximo(ponto + deslocamento))
							task.wait(ESPERA_CARREGAR)
							if #varrerDoces() > 0 then break end
						end
	
						task.wait(ESPERA_PONTO)
					end
				end
			end
			rodando = false
		end)
	end
	
	local function atualizarVisual()
		if not botao.Parent then return end
		botao.BackgroundColor3 = ativo and COR_ATIVA or corOriginal
	end
	
	local function alternar()
		if not vivo then return end
		ativo = not ativo
		atualizarVisual()
		if ativo then
			conectarPasta()
			rodada()
		end
	end
	
	-- ------------------------------------------------------------------
	-- Atalho exatamente no estilo do sistema HPX Bones
	-- ------------------------------------------------------------------
	local keyButton = botao:FindFirstChild("keybutton", true)
		or botao:FindFirstChild("keybuton", true)
		or botao:FindFirstChild("key", true)
		or botao:FindFirstChild("tecla", true)
	
	-- Se o keybutton for um Frame, procura o campo dentro dele.
	if keyButton and not (keyButton:IsA("TextBox") or keyButton:IsA("TextButton")) then
		keyButton = keyButton:FindFirstChildWhichIsA("TextBox", true)
			or keyButton:FindFirstChildWhichIsA("TextButton", true)
	end
	
	-- Registro de atalhos: usa _G/getgenv para ser compartilhado com
	-- Bones/Lobo/Potions mesmo com o codigo ofuscado.
	local function registroAtalhos()
		local env = nil
		if type(getgenv) == "function" then
			env = getgenv()
		elseif type(getfenv) == "function" then
			env = getfenv(0)
		end
		if type(env) == "table" then
			env.HPX_Atalhos = env.HPX_Atalhos or {}
			return env.HPX_Atalhos
		end
		_G.HPX_Atalhos = _G.HPX_Atalhos or {}
		return _G.HPX_Atalhos
	end
	
	local TECLA_ATIVAR = nil
	local numeros = {"Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"}
	local atualizandoTextoTecla = false
	local avisoSequencia = 0
	local capturando = false
	
	local function nomeVisivel(keyCode)
		if not keyCode then return nil end
		for i, nome in ipairs(numeros) do
			if keyCode.Name == nome then return tostring(i - 1) end
		end
		return keyCode.Name
	end
	
	local function atualizarTextoTecla()
		if not keyButton or not keyButton.Parent then return end
		atualizandoTextoTecla = true
		keyButton.Text = TECLA_ATIVAR and nomeVisivel(TECLA_ATIVAR) or "-"
		atualizandoTextoTecla = false
	end
	
	local function obterTecla(texto)
		local nome = string.upper((texto or ""):sub(1, 1))
		if #nome ~= 1 then return nil end
		local codigo = string.byte(nome)
		if not codigo or not ((codigo >= 48 and codigo <= 57) or (codigo >= 65 and codigo <= 90)) then
			return nil
		end
		if codigo >= 48 and codigo <= 57 then
			return Enum.KeyCode[numeros[codigo - 47]]
		end
		return Enum.KeyCode[nome]
	end
	
	local function donoDaTecla(nome)
		local reg = registroAtalhos()
		if typeof(reg) == "Instance" then
			local v = reg:FindFirstChild(nome)
			return v and v:IsA("StringValue") and v.Value or nil
		end
		if type(reg) == "table" then
			local v = reg[nome]
			return typeof(v) == "Instance" and v:IsA("StringValue") and v.Value or v
		end
	end
	
	local function gravarDono(nome, dono)
		local reg = registroAtalhos()
		if typeof(reg) == "Instance" then
			local v = reg:FindFirstChild(nome)
			if dono then
				if not v then
					v = Instance.new("StringValue")
					v.Name = nome
					v.Parent = reg
				end
				if v:IsA("StringValue") then v.Value = dono end
			elseif v and v:IsA("StringValue") and v.Value == IDENTIFICADOR then
				v:Destroy()
			end
		elseif type(reg) == "table" then
			if dono or reg[nome] == IDENTIFICADOR then reg[nome] = dono end
		end
	end
	
	local function definirTecla(keyCode)
		if not keyCode or keyCode == Enum.KeyCode.Unknown then return end
		local nome = nomeVisivel(keyCode)
		local dono = donoDaTecla(nome) or donoDaTecla(keyCode.Name)
		if dono and dono ~= "" and dono ~= IDENTIFICADOR then
			avisoSequencia = avisoSequencia + 1
			local seq = avisoSequencia
			if keyButton then
				atualizandoTextoTecla = true
				keyButton.Text = "USADA"
				atualizandoTextoTecla = false
			end
			task.delay(1.2, function()
				if vivo and seq == avisoSequencia then atualizarTextoTecla() end
			end)
			return
		end
		avisoSequencia = avisoSequencia + 1
		if TECLA_ATIVAR then
			local antiga = nomeVisivel(TECLA_ATIVAR)
			gravarDono(antiga, nil)
			if antiga ~= TECLA_ATIVAR.Name then gravarDono(TECLA_ATIVAR.Name, nil) end
		end
		TECLA_ATIVAR = keyCode
		gravarDono(nome, IDENTIFICADOR)
		atualizarTextoTecla()
		if keyButton and keyButton:IsA("TextBox") and keyButton:IsFocused() then
			keyButton:ReleaseFocus()
		end
	end
	
	if keyButton and keyButton:IsA("TextBox") then
		keyButton.TextEditable = true
		keyButton.ClearTextOnFocus = false
		local inicial = obterTecla(keyButton.Text)
		if inicial then definirTecla(inicial) end
		table.insert(conexoes, keyButton:GetPropertyChangedSignal("Text"):Connect(function()
			if atualizandoTextoTecla then return end
			local primeiro = string.upper(keyButton.Text or ""):sub(1, 1)
			local tecla = obterTecla(primeiro)
			atualizandoTextoTecla = true
			keyButton.Text = tecla and primeiro or ""
			atualizandoTextoTecla = false
			if tecla then definirTecla(tecla) end
		end))
		table.insert(conexoes, keyButton.FocusLost:Connect(atualizarTextoTecla))
	elseif keyButton and keyButton:IsA("TextButton") then
		local inicial = obterTecla(keyButton.Text)
		if inicial then definirTecla(inicial) end
		table.insert(conexoes, keyButton.Activated:Connect(function()
			capturando = true
			keyButton.Text = "..."
		end))
	end
	
	table.insert(conexoes, botao.Activated:Connect(function()
		if capturando then return end
		alternar()
	end))
	
	table.insert(conexoes, UIS.InputBegan:Connect(function(input, processado)
		if not vivo or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
		if capturando then
			capturando = false
			local tecla = obterTecla(nomeVisivel(input.KeyCode))
			if tecla then definirTecla(tecla) else atualizarTextoTecla() end
			return
		end
		if processado or UIS:GetFocusedTextBox() then return end
		if TECLA_ATIVAR and input.KeyCode == TECLA_ATIVAR then alternar() end
	end))
	
	_G.HPX_CandyRota_Parar = function()
		vivo, ativo = false, false
		if TECLA_ATIVAR then
			local nome = nomeVisivel(TECLA_ATIVAR)
			gravarDono(nome, nil)
			if nome ~= TECLA_ATIVAR.Name then gravarDono(TECLA_ATIVAR.Name, nil) end
		end
		atualizarVisual()
		if conexaoPasta then conexaoPasta:Disconnect() end
		for _, c in ipairs(conexoes) do c:Disconnect() end
	end
	
	table.insert(conexoes, botao.Destroying:Connect(function()
		if vivo then _G.HPX_CandyRota_Parar() end
	end))
	
	atualizarTextoTecla()
	atualizarVisual()
	conectarPasta()
	
end
local function HZNIK_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.voxUp.RoVibes.BoneButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_BoneButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")
	
	local player = Players.LocalPlayer
	
	local OSSOS_NECESSARIOS = 10
	
	local RAIO_SCAN = 2200
	local PASSO_SCAN = 450
	
	local RAIO_SCAN_FINO = 1000
	local PASSO_SCAN_FINO = 150
	
	local RAIO_SCAN_EXTRA = 2200
	local PASSO_SCAN_EXTRA = 110
	
	local TEMPO_ANALISE = 0.25
	local TEMPO_ANALISE_FINA = 0.3
	local TEMPO_ANALISE_EXTRA = 0.35
	
	local TEMPO_MAX_COLETA = 1.5
	local INTERVALO_COLETA = 0.04
	
	local INTERVALO_CICLOS = 0.5
	local TEMPO_COOLDOWN_BONE = 5
	
	local ativo = false
	local executando = false
	local geracao = 0
	
	local ossosInicial = 0
	local coletadosSessao = 0
	local ultimaQuantidadeGUI = nil
	
	local contados = {}
	local cooldownBones = {}
	
	local ciclo = 0
	local proximaTentativaSkeleton = 0
	local atualizarBotao = function() end
	
	local function pareceAsaDeOssos(obj)
		if not obj then
			return false
		end
	
		local nome = obj.Name:lower():gsub("[%s_%-]", "")
		return nome == "bonewings"
			or nome == "bonewing"
			or nome == "asadeossos"
			or nome == "asaossos"
	end
	
	local function procurarAsaDeOssos(container)
		if not container then
			return nil
		end
	
		for _, obj in ipairs(container:GetDescendants()) do
			if pareceAsaDeOssos(obj) then
				return obj
			end
		end
	
		return nil
	end
	
	local function funcionando(token)
		return ativo and geracao == token
	end
	
	local function esperar(tempo, token)
		local fim = os.clock() + tempo
	
		while funcionando(token) and os.clock() < fim do
			task.wait(math.min(0.05, fim - os.clock()))
		end
	
		return funcionando(token)
	end
	
	local function temAsa()
		local backpack = player:FindFirstChild("Backpack")
	
		if backpack then
			local fly = backpack:FindFirstChild("Fly")
	
			if fly and fly:IsA("Tool") then
				return true, fly
			end
	
			local boneWings = procurarAsaDeOssos(backpack)
			if boneWings then
				return true, boneWings
			end
		end
	
		local character = player.Character
	
		if character then
			local fly = character:FindFirstChild("Fly")
	
			if fly and fly:IsA("Tool") then
				return true, fly
			end
	
			local asa = character:FindFirstChild("AsaClone")
	
			if asa then
				return true, asa
			end
	
			local boneWings = procurarAsaDeOssos(character)
			if boneWings then
				return true, boneWings
			end
		end
	
		return false, nil
	end
	
	local function personagem()
		local character = player.Character
	
		if not character then
			return nil
		end
	
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		local root = character:FindFirstChild("HumanoidRootPart")
	
		if not humanoid or not root or humanoid.Health <= 0 then
			return nil
		end
	
		return character, humanoid, root
	end
	
	local function lerQuantidadeOssos()
		local gui = player:FindFirstChild("PlayerGui")
	
		if not gui then
			return nil
		end
	
		for _, obj in ipairs(gui:GetDescendants()) do
			if obj:IsA("TextLabel") or obj:IsA("TextButton") then
				local texto = obj.Text:lower():gsub("%s+", " ")
	
				local numero =
					texto:match("voc[e�] tem%s+(%d+)%s+ossos")
					or texto:match("ossos%s*:%s*(%d+)")
					or texto:match("ossos?%s*:?%s*(%d+)%s*/%s*%d+")
					or texto:match("bones?%s*:?%s*(%d+)%s*/%s*%d+")
					or texto:match("you have%s+(%d+)%s+bones")
					or texto:match("bones?%s*:%s*(%d+)")
	
				if not numero and (texto:find("ossos", 1, true) or texto:find("bones", 1, true)) then
					local atual = obj.Parent
					for _ = 1, 2 do
						if not atual then
							break
						end
	
						for _, filho in ipairs(atual:GetDescendants()) do
							if filho:IsA("TextLabel") or filho:IsA("TextButton") then
								local valor = filho.Text:match("(%d+)%s*/%s*%d+")
								if valor then
									return tonumber(valor)
								end
							end
						end
	
						atual = atual.Parent
					end
				end
	
				if numero then
					return tonumber(numero)
				end
			end
		end
	
		return nil
	end
	
	local function quantidadeAtual()
		local gui = lerQuantidadeOssos()
	
		if gui ~= nil then
			ultimaQuantidadeGUI = gui
	
			return math.max(
				gui,
				ossosInicial + coletadosSessao
			)
		end
	
		return ossosInicial + coletadosSessao
	end
	
	local function atualizarQuantidade()
		local gui = lerQuantidadeOssos()
	
		if gui ~= nil then
			ultimaQuantidadeGUI = gui
	
			local estimado = ossosInicial + coletadosSessao
	
			if gui > estimado then
				ossosInicial = gui
				coletadosSessao = 0
			end
		end
	end
	
	local function pegarPastaBones()
		return workspace:FindFirstChild("BonesLocal")
	end
	
	local function pegarParteBone(model)
		if not model then
			return nil
		end
	
		if model:IsA("BasePart") then
			return model
		end
	
		local stack = model:FindFirstChild("stack", true)
	
		if stack and stack:IsA("BasePart") then
			return stack
		end
	
		if model:IsA("Model") and model.PrimaryPart then
			return model.PrimaryPart
		end
	
		return model:FindFirstChildWhichIsA("BasePart", true)
	end
	
	local function boneExiste(model)
		local pasta = pegarPastaBones()
	
		return model ~= nil
			and model.Parent ~= nil
			and pasta ~= nil
			and model:IsDescendantOf(pasta)
	end
	
	local function alturaPersonagem()
		local character, humanoid, root = personagem()
	
		if not character then
			return 3
		end
	
		local altura = humanoid.HipHeight + root.Size.Y / 2
	
		if humanoid.RigType == Enum.HumanoidRigType.R6 then
			local perna = character:FindFirstChild("Left Leg")
	
			if perna then
				altura += perna.Size.Y
			end
		end
	
		return altura
	end
	
	local function procurarChaoTerrain(posicao, token)
		local ignorar = {}
	
		if player.Character then
			table.insert(ignorar, player.Character)
		end
	
		local bones = pegarPastaBones()
	
		if bones then
			table.insert(ignorar, bones)
		end
	
		for _ = 1, 30 do
			if not funcionando(token) then
				return nil
			end
	
			local params = RaycastParams.new()
	
			params.FilterType = Enum.RaycastFilterType.Exclude
			params.FilterDescendantsInstances = ignorar
	
			local resultado = workspace:Raycast(
				Vector3.new(posicao.X, 1200, posicao.Z),
				Vector3.new(0, -2400, 0),
				params
			)
	
			if not resultado then
				return nil
			end
	
			if resultado.Instance == workspace.Terrain then
				if resultado.Material ~= Enum.Material.Water then
					return resultado.Position
				end
	
				return nil
			end
	
			table.insert(ignorar, resultado.Instance)
		end
	
		return nil
	end
	
	local function teleportarNoChao(posicao, token)
		if not funcionando(token) then
			return false
		end
	
		local character, humanoid, root = personagem()
	
		if not character then
			return false
		end
	
		local destino = posicao + Vector3.new(
			0,
			alturaPersonagem() + 0.1,
			0
		)
	
		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
	
		character:PivotTo(CFrame.new(destino))
	
		pcall(function()
			humanoid:ChangeState(Enum.HumanoidStateType.Running)
		end)
	
		RunService.Heartbeat:Wait()
	
		return funcionando(token)
	end
	
	local function posicaoPrompt(prompt)
		if not prompt or not prompt.Parent then
			return nil
		end
	
		local parent = prompt.Parent
	
		if parent:IsA("Attachment") then
			return parent.WorldPosition
		end
	
		if parent:IsA("BasePart") then
			return parent.Position
		end
	
		local parte = parent:FindFirstChildWhichIsA("BasePart", true)
	
		return parte and parte.Position or nil
	end
	
	local function irParaBancada(prompt, token)
		if not funcionando(token) then
			return false
		end
	
		local pos = posicaoPrompt(prompt)
	
		if not pos then
			return false
		end
	
		local character, humanoid, root = personagem()
	
		if not character then
			return false
		end
	
		local direcao = root.Position - pos
	
		direcao = Vector3.new(direcao.X, 0, direcao.Z)
	
		if direcao.Magnitude < 0.1 then
			direcao = Vector3.new(1, 0, 0)
		else
			direcao = direcao.Unit
		end
	
		local alcance = math.max(
			1.2,
			math.min(2, prompt.MaxActivationDistance * 0.5)
		)
	
		local alvo = pos + direcao * alcance
	
		local chao = procurarChaoTerrain(alvo, token)
	
		if chao then
			teleportarNoChao(chao, token)
		else
			character:PivotTo(
				CFrame.new(alvo.X, pos.Y + 2, alvo.Z)
			)
		end
	
		if not esperar(0.15, token) then
			return false
		end
	
		local _, _, rootAtual = personagem()
	
		if rootAtual then
			local olhar = Vector3.new(
				pos.X,
				rootAtual.Position.Y,
				pos.Z
			)
	
			if (olhar - rootAtual.Position).Magnitude > 0.05 then
				rootAtual.CFrame = CFrame.lookAt(
					rootAtual.Position,
					olhar
				)
			end
		end
	
		return funcionando(token)
	end
	
	local function ativarPrompt(prompt, token)
		if not funcionando(token)
			or not prompt
			or not prompt.Parent
			or not prompt.Enabled then
	
			return false
		end
	
		local disparou = false
	
		local conexao = prompt.Triggered:Connect(function()
			disparou = true
		end)
	
		local usouFire = false
	
		if type(fireproximityprompt) == "function" then
			local ok = pcall(function()
				fireproximityprompt(prompt)
			end)
	
			usouFire = ok
		end
	
		if usouFire then
			esperar(
				math.max(prompt.HoldDuration + 0.2, 0.3),
				token
			)
		end
	
		if not disparou and funcionando(token) then
			local iniciou = false
	
			local ok, erro = pcall(function()
				prompt:InputHoldBegin()
				iniciou = true
			end)
	
			if ok and iniciou then
				esperar(
					math.max(prompt.HoldDuration + 0.3, 0.3),
					token
				)
	
				pcall(function()
					prompt:InputHoldEnd()
				end)
			else
				warn("[HPX BONES] Erro no prompt:", erro)
			end
		end
	
		if conexao then
			conexao:Disconnect()
		end
	
		return disparou
	end
	
	local function textoDaGui(obj)
		local partes = {}
	
		if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
			table.insert(partes, obj.Text)
		end
	
		for _, filho in ipairs(obj:GetDescendants()) do
			if filho:IsA("TextLabel") or filho:IsA("TextButton") or filho:IsA("TextBox") then
				table.insert(partes, filho.Text)
			end
		end
	
		return table.concat(partes, " "):lower():gsub("%s+", " ")
	end
	
	local function guiEstaVisivel(obj)
		local atual = obj
		while atual and atual ~= player do
			if atual:IsA("ScreenGui") and not atual.Enabled then
				return false
			end
			if atual:IsA("GuiObject") and not atual.Visible then
				return false
			end
			atual = atual.Parent
		end
		return true
	end
	
	local function pegarPlayerGui()
		return player:FindFirstChildOfClass("PlayerGui") or player:FindFirstChild("PlayerGui")
	end
	
	local function acharPainelBoneCraft()
		local gui = pegarPlayerGui()
		if not gui then
			return nil
		end
	
		for _, obj in ipairs(gui:GetDescendants()) do
			if (obj:IsA("TextLabel") or obj:IsA("TextButton"))
				and guiEstaVisivel(obj)
				and obj.Text:lower():find("bone crafting", 1, true) then
	
				local atual = obj
				while atual and atual ~= gui do
					if atual:IsA("ScreenGui") then
						return atual
					end
					atual = atual.Parent
				end
	
				return obj.Parent
			end
		end
	
		return nil
	end
	
	local function painelJaCraftado(painel)
		if not painel then
			return false
		end
	
		for _, obj in ipairs(painel:GetDescendants()) do
			if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and guiEstaVisivel(obj) then
				local texto = obj.Text:lower()
				if texto:find("crafted", 1, true)
					or texto:find("craftado", 1, true)
					or texto:find("fabricado", 1, true) then
					return true
				end
			end
		end
	
		return false
	end
	
	local function acharBotaoBoneWings(raiz, exigirAcaoCraft)
		if not raiz then
			return nil
		end
	
		for _, obj in ipairs(raiz:GetDescendants()) do
			if obj:IsA("GuiButton") and obj.Active and guiEstaVisivel(obj) then
				local texto = textoDaGui(obj)
				local bone = texto:find("bone", 1, true) or texto:find("osso", 1, true)
				local wings = texto:find("wing", 1, true) or texto:find("asa", 1, true)
				local craft = texto:find("craft", 1, true) or texto:find("criar", 1, true)
				local crafted = texto:find("crafted", 1, true) or texto:find("craftado", 1, true)
	
				if exigirAcaoCraft then
					if craft and not crafted then
						return obj
					end
				elseif bone and wings and craft and not crafted then
					return obj
				end
			end
		end
	
		return nil
	end
	
	local function clicarBotaoGui(botao)
		if not botao then
			return false
		end
	
		local ok = pcall(function()
			botao:Activate()
		end)
		if ok then
			return true
		end
	
		if type(firesignal) == "function" then
			ok = pcall(function()
				firesignal(botao.Activated)
			end)
			if ok then
				return true
			end
	
			if botao:IsA("TextButton") then
				ok = pcall(function()
					firesignal(botao.MouseButton1Click)
				end)
				if ok then
					return true
				end
			end
		end
	
		return false
	end
	
	local function aguardarPainelBoneCraft(token, tempo)
		local fim = os.clock() + tempo
		while funcionando(token) and os.clock() < fim do
			local painel = acharPainelBoneCraft()
			if painel then
				return painel
			end
			task.wait(0.1)
		end
		return nil
	end
	
	local function acharEsqueleto()
		local pasta = workspace:FindFirstChild("NPCs")
		if pasta then
			for _, obj in ipairs(pasta:GetChildren()) do
				if obj.Name:lower() == "skeleton" or obj.Name:lower() == "esqueleto" then
					return obj
				end
			end
		end
	
		for _, obj in ipairs(workspace:GetDescendants()) do
			if obj.Name:lower() == "skeleton" or obj.Name:lower() == "esqueleto" then
				return obj
			end
		end
	
		return nil
	end
	
	local function acharInteracaoEsqueleto(esqueleto)
		local melhorPrompt = nil
		local melhorPontos = -math.huge
		local clickDetector = nil
	
		for _, obj in ipairs(esqueleto:GetDescendants()) do
			if obj:IsA("ProximityPrompt") and obj.Enabled then
				local contexto = (obj.Name .. " " .. obj.ActionText .. " " .. obj.ObjectText):lower()
				local pontos = 1
	
				if contexto:find("talk", 1, true)
					or contexto:find("speak", 1, true)
					or contexto:find("interact", 1, true)
					or contexto:find("falar", 1, true)
					or contexto:find("convers", 1, true) then
					pontos += 100
				end
				if contexto:find("skeleton", 1, true) or contexto:find("esqueleto", 1, true) then
					pontos += 20
				end
	
				local atual = obj.Parent
				while atual and atual ~= esqueleto do
					local nome = atual.Name:lower()
					if nome:find("mesa", 1, true) or nome:find("table", 1, true) or nome:find("craft", 1, true) then
						pontos -= 200
					end
					atual = atual.Parent
				end
	
				if pontos > melhorPontos then
					melhorPontos = pontos
					melhorPrompt = obj
				end
			elseif obj:IsA("ClickDetector") and not clickDetector then
				clickDetector = obj
			end
		end
	
		if melhorPrompt and melhorPontos > 0 then
			return melhorPrompt, nil
		end
		return nil, clickDetector
	end
	
	local function falarComEsqueleto(token)
		local esqueleto = acharEsqueleto()
		if not esqueleto then
			warn("[HPX BONES] Pasta NPCs/Skeleton nao encontrada.")
			return false
		end
	
		local prompt, clickDetector = acharInteracaoEsqueleto(esqueleto)
		if prompt then
			print("[HPX BONES] Interagindo com NPC Skeleton.")
			if not irParaBancada(prompt, token) then
				return false
			end
			ativarPrompt(prompt, token)
			return esperar(0.4, token)
		end
	
		if clickDetector and type(fireclickdetector) == "function" then
			local parte = clickDetector.Parent
			if parte and parte:IsA("BasePart") then
				local _, _, root = personagem()
				if root then
					local direcao = root.Position - parte.Position
					direcao = Vector3.new(direcao.X, 0, direcao.Z)
					if direcao.Magnitude < 0.1 then
						direcao = Vector3.new(1, 0, 0)
					else
						direcao = direcao.Unit
					end
					local alvo = parte.Position + direcao * 3
					local chao = procurarChaoTerrain(alvo, token)
					if chao then
						teleportarNoChao(chao, token)
					end
				end
			end
	
			local ok = pcall(function()
				fireclickdetector(clickDetector)
			end)
			return ok and esperar(0.4, token)
		end
	
		warn("[HPX BONES] Interacao do NPC Skeleton nao encontrada.")
		return false
	end
	
	local function tentarCriar(token)
		if not funcionando(token) then
			return false
		end
	
		local painel = acharPainelBoneCraft()
		if painelJaCraftado(painel) then
			print("[HPX BONES] Bone Wings ja aparece como Crafted.")
			return true
		end
	
		local tem, item = temAsa()
		if tem then
			print("[HPX BONES] Asa ja encontrada:", item:GetFullName())
			return true
		end
	
		local playerGui = pegarPlayerGui()
		local botaoDialogo = acharBotaoBoneWings(playerGui, false)
	
		if not painel and not botaoDialogo and os.clock() >= proximaTentativaSkeleton then
			proximaTentativaSkeleton = os.clock() + 4
			falarComEsqueleto(token)
	
			local fim = os.clock() + 3
			while funcionando(token) and os.clock() < fim do
				painel = acharPainelBoneCraft()
				botaoDialogo = acharBotaoBoneWings(playerGui, false)
				if painel or botaoDialogo then
					break
				end
				task.wait(0.1)
			end
		end
	
		if not painel then
			botaoDialogo = botaoDialogo or acharBotaoBoneWings(playerGui, false)
			if botaoDialogo then
				print("[HPX BONES] Abrindo a receita Bone Wings.")
				clicarBotaoGui(botaoDialogo)
				painel = aguardarPainelBoneCraft(token, 4)
			end
		end
	
		if not funcionando(token) then
			return false
		end
	
		if not painel then
			if quantidadeAtual() >= OSSOS_NECESSARIOS then
				warn("[HPX BONES] Painel Bone Crafting nao abriu depois da conversa com Skeleton.")
			end
			return false
		end
	
		if painelJaCraftado(painel) then
			print("[HPX BONES] Bone Wings ja esta Crafted; nao vou craftar novamente.")
			return true
		end
	
		atualizarQuantidade()
		if quantidadeAtual() < OSSOS_NECESSARIOS then
			return false
		end
	
		local botaoCraft = acharBotaoBoneWings(painel, true)
		if not botaoCraft then
			warn("[HPX BONES] Botao Craft nao encontrado no painel Bone Crafting.")
			return false
		end
	
		print("[HPX BONES] 10 ossos encontrados; clicando em Craft.")
		clicarBotaoGui(botaoCraft)
	
		local fim = os.clock() + 6
		while funcionando(token) and os.clock() < fim do
			painel = acharPainelBoneCraft()
			if painelJaCraftado(painel) then
				print("[HPX BONES] Bone Wings craftado com sucesso.")
				return true
			end
	
			local temDepois, itemDepois = temAsa()
			if temDepois then
				print("[HPX BONES] Asa obtida:", itemDepois:GetFullName())
				return true
			end
	
			task.wait(0.15)
		end
	
		warn("[HPX BONES] Ainda nao consegui confirmar o craft de Bone Wings.")
		return false
	end
	local function listarBones()
		local pasta = pegarPastaBones()
	
		if not pasta then
			return {}
		end
	
		local _, _, root = personagem()
	
		if not root then
			return {}
		end
	
		local lista = {}
		local agora = os.clock()
	
		for _, obj in ipairs(pasta:GetDescendants()) do
			if obj:IsA("Model")
				and not contados[obj]
				and (not cooldownBones[obj] or cooldownBones[obj] <= agora) then
	
				local parte = pegarParteBone(obj)
	
				if parte then
					table.insert(lista, {
						Model = obj,
						Distancia = (root.Position - parte.Position).Magnitude
					})
				end
			end
		end
	
		table.sort(lista, function(a, b)
			return a.Distancia < b.Distancia
		end)
	
		return lista
	end
	
	local function tocarBone(model, token)
		local _, _, root = personagem()
	
		if not root then
			return
		end
	
		if type(firetouchinterest) ~= "function" then
			return
		end
	
		local partes = {}
	
		if model:IsA("BasePart") then
			table.insert(partes, model)
		end
	
		for _, obj in ipairs(model:GetDescendants()) do
			if obj:IsA("BasePart") then
				table.insert(partes, obj)
			end
		end
	
		for _, parte in ipairs(partes) do
			if not funcionando(token) then
				return
			end
	
			pcall(function()
				firetouchinterest(root, parte, 0)
				task.wait()
				firetouchinterest(root, parte, 1)
			end)
		end
	end
	
	local function registrarColeta(model)
		if contados[model] then
			return
		end
	
		contados[model] = true
		coletadosSessao += 1
	
	
	end
	
	local function coletarBone(model, token)
		if not funcionando(token) or not boneExiste(model) then
			return false
		end
	
		local inicio = os.clock()
		local antes = quantidadeAtual()
	
		while funcionando(token)
			and boneExiste(model)
			and os.clock() - inicio < TEMPO_MAX_COLETA do
	
			local parte = pegarParteBone(model)
	
			if not parte then
				break
			end
	
			local character, humanoid = personagem()
	
			if not character then
				break
			end
	
			character:PivotTo(
				CFrame.new(
					parte.Position.X,
					parte.Position.Y + 1.3,
					parte.Position.Z
				)
			)
	
			pcall(function()
				humanoid:ChangeState(Enum.HumanoidStateType.Running)
			end)
	
			humanoid:Move(Vector3.new(0.06, 0, 0), false)
	
			tocarBone(model, token)
	
			if not esperar(INTERVALO_COLETA, token) then
				return false
			end
	
			if not boneExiste(model) then
				registrarColeta(model)
				return true
			end
	
			local depois = quantidadeAtual()
	
			if depois > antes then
				contados[model] = true
	
	
				return true
			end
		end
	
		if not boneExiste(model) and funcionando(token) then
			registrarColeta(model)
			return true
		end
	
		cooldownBones[model] = os.clock() + TEMPO_COOLDOWN_BONE
	
		return false
	end
	
	local function analisarArea(tempo, token)
		local fim = os.clock() + tempo
	
		while funcionando(token) and os.clock() < fim do
			if temAsa() then
				return "asa"
			end
	
			if quantidadeAtual() >= OSSOS_NECESSARIOS then
				return "bancada"
			end
	
			local lista = listarBones()
	
			for _, info in ipairs(lista) do
				if not funcionando(token) then
					return "cancelado"
				end
	
				if boneExiste(info.Model) then
					coletarBone(info.Model, token)
				end
	
				if temAsa() then
					return "asa"
				end
	
				if quantidadeAtual() >= OSSOS_NECESSARIOS then
					return "bancada"
				end
			end
	
			if not esperar(0.03, token) then
				return "cancelado"
			end
		end
	
		return "continuar"
	end
	
	local function gerarPontos(origem, raioMaximo, passo)
		local pontos = {origem}
	
		for raio = passo, raioMaximo, passo do
			local quantidade = math.max(
				8,
				math.floor(2 * math.pi * raio / passo)
			)
	
			for i = 1, quantidade do
				local angulo = (i / quantidade) * math.pi * 2
	
				table.insert(
					pontos,
					Vector3.new(
						origem.X + math.cos(angulo) * raio,
						origem.Y,
						origem.Z + math.sin(angulo) * raio
					)
				)
			end
		end
	
		return pontos
	end
	
	local function executarScan(origem, raio, passo, tempo, token)
		local pontos = gerarPontos(origem, raio, passo)
	
	
		for i, ponto in ipairs(pontos) do
			if not funcionando(token) then
				return "cancelado"
			end
	
			if temAsa() then
				return "asa"
			end
	
			if quantidadeAtual() >= OSSOS_NECESSARIOS then
				return "bancada"
			end
	
			local chao = procurarChaoTerrain(ponto, token)
	
			if chao then
				local teleportou = teleportarNoChao(chao, token)
	
				if teleportou then
					local resultado = analisarArea(tempo, token)
	
					if resultado ~= "continuar" then
						return resultado
					end
				end
			end
	
		end
	
		return "finalizado"
	end
	
	local function iniciar(token)
		local terminouNormalmente = false
	
		local ok, erro = pcall(function()
			local character, humanoid, root = personagem()
	
			if not root then
				warn("[HPX BONES] Personagem n�o encontrado.")
				return
			end
	
			local origem = root.Position
	
			local inicial = lerQuantidadeOssos()
	
			if inicial ~= nil then
				ossosInicial = inicial
			else
				ossosInicial = 0
			end
	
	
			while funcionando(token) do
				local tem, item = temAsa()
	
				if tem then
					print("[HPX BONES] ? Voc� j� tem a asa!")
	
					terminouNormalmente = true
					break
				end
	
				ciclo += 1
	
	
				local criou = tentarCriar(token)
	
				if not funcionando(token) then
					break
				end
	
				if criou or temAsa() then
					print("[HPX BONES] ? Asa obtida!")
					terminouNormalmente = true
					break
				end
	
	
				local resultado
	
				if quantidadeAtual() < OSSOS_NECESSARIOS then
					if ciclo == 1 then
						resultado = executarScan(
							origem,
							RAIO_SCAN,
							PASSO_SCAN,
							TEMPO_ANALISE,
							token
						)
					elseif ciclo == 2 then
						resultado = executarScan(
							origem,
							RAIO_SCAN_FINO,
							PASSO_SCAN_FINO,
							TEMPO_ANALISE_FINA,
							token
						)
					else
						resultado = executarScan(
							origem,
							RAIO_SCAN_EXTRA,
							PASSO_SCAN_EXTRA,
							TEMPO_ANALISE_EXTRA,
							token
						)
					end
				else
					resultado = "bancada"
				end
	
				if not funcionando(token) then
					break
				end
	
				if resultado == "asa" then
					terminouNormalmente = true
					break
				end
	
	
				local conseguiu = tentarCriar(token)
	
				if not funcionando(token) then
					break
				end
	
				if conseguiu or temAsa() then
					print(
						"[HPX BONES] ? Asa criada com sucesso!"
					)
	
					terminouNormalmente = true
					break
				end
	
	
				if not esperar(INTERVALO_CICLOS, token) then
					break
				end
			end
		end)
	
		if not ok then
			warn("[HPX BONES] Erro:", erro)
		end
	
		if geracao == token then
			ativo = false
			atualizarBotao()
	
			if terminouNormalmente then
				print(
					"[HPX BONES] ? Processo finalizado automaticamente."
				)
			end
		end
	
		executando = false
	end
	
	local function alternar()
		if ativo then
			ativo = false
			geracao += 1
			atualizarBotao()
	
			print("[HPX BONES] ? DESATIVADO")
	
			return
		end
	
		local tem, item = temAsa()
	
		if tem then
			print("[HPX BONES] ? Voc� j� possui a asa.")
			print("[HPX BONES] Item:", item:GetFullName())
			return
		end
	
		if executando then
			warn("[HPX BONES] Aguardando a execu��o anterior encerrar.")
			return
		end
	
		ativo = true
		executando = true
		geracao += 1
	
		local token = geracao
		atualizarBotao()
	
		contados = {}
		cooldownBones = {}
	
		ossosInicial = 0
		coletadosSessao = 0
		ultimaQuantidadeGUI = nil
		ciclo = 0
		proximaTentativaSkeleton = 0
	
		print("[HPX BONES] ? ATIVADO")
	
		task.spawn(function()
			iniciar(token)
		end)
	end
	
	
	local playerGui = player:WaitForChild("PlayerGui")
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	local OWNER = "Osso"
	
	local function encontrarBotao()
		for _, obj in ipairs(playerGui:GetDescendants()) do
			if obj.Name == "BoneButton" and obj:IsA("GuiButton") then
				return obj
			end
		end
		return nil
	end
	
	local boneButton = encontrarBotao()
	if not boneButton then
		warn("[HPX BONES] BoneButton n�o encontrado no PlayerGui.")
		return
	end
	
	local keyButton = boneButton:FindFirstChild("keybutton", true)
		or boneButton:FindFirstChild("keybuton", true)
		or boneButton:FindFirstChild("key", true)
		or boneButton:FindFirstChild("tecla", true)
	
	local corOriginal = boneButton.BackgroundColor3
	local corAtiva = Color3.fromRGB(0, 170, 0)
	local TECLA_ATIVAR = nil
	local numeros = {"Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"}
	local function nomeVisivel(keyCode)
		if not keyCode then return nil end
		for i, nome in ipairs(numeros) do
			if keyCode.Name == nome then return tostring(i - 1) end
		end
		return keyCode.Name
	end
	local atualizandoTextoTecla = false
	local avisoSequencia = 0
	local capturando = false
	
	atualizarBotao = function()
		if boneButton and boneButton.Parent then
			boneButton.BackgroundColor3 = ativo and corAtiva or corOriginal
		end
	end
	
	local function atualizarTextoTecla()
		if not keyButton or not keyButton.Parent then return end
		local texto = TECLA_ATIVAR and nomeVisivel(TECLA_ATIVAR) or "-"
		atualizandoTextoTecla = true
		keyButton.Text = texto
		atualizandoTextoTecla = false
	end
	
	local function obterTecla(texto)
		local nome = string.upper((texto or ""):sub(1, 1))
		if #nome ~= 1 then return nil end
		local codigo = string.byte(nome)
		if not ((codigo >= 48 and codigo <= 57) or (codigo >= 65 and codigo <= 90)) then
			return nil
		end
		if codigo >= 48 and codigo <= 57 then
			return Enum.KeyCode[numeros[codigo - 47]]
		end
		return Enum.KeyCode[nome]
	end
	
	local function definirTecla(keyCode)
		if not keyCode or keyCode == Enum.KeyCode.Unknown then return end
		local nome = nomeVisivel(keyCode)
		local dono = _G.HPX_Atalhos[nome]
	
		if dono and dono ~= OWNER then
			avisoSequencia += 1
			local seq = avisoSequencia
			if keyButton then
				atualizandoTextoTecla = true
				keyButton.Text = "USADA"
				atualizandoTextoTecla = false
			end
			task.delay(1.2, function()
				if seq == avisoSequencia then atualizarTextoTecla() end
			end)
			return
		end
	
		avisoSequencia += 1
		if TECLA_ATIVAR and _G.HPX_Atalhos[nomeVisivel(TECLA_ATIVAR)] == OWNER then
			_G.HPX_Atalhos[nomeVisivel(TECLA_ATIVAR)] = nil
		end
		TECLA_ATIVAR = keyCode
		_G.HPX_Atalhos[nome] = OWNER
		atualizarTextoTecla()
	
		if keyButton and keyButton:IsA("TextBox") and keyButton:IsFocused() then
			keyButton:ReleaseFocus()
		end
	end
	
	if keyButton and keyButton:IsA("TextBox") then
		keyButton.TextEditable = true
		keyButton.ClearTextOnFocus = false
		local inicial = obterTecla(keyButton.Text)
		if inicial then definirTecla(inicial) end
	
		keyButton:GetPropertyChangedSignal("Text"):Connect(function()
			if atualizandoTextoTecla then return end
			local texto = string.upper(keyButton.Text or "")
			local primeiro = texto:sub(1, 1)
			local tecla = obterTecla(primeiro)
			atualizandoTextoTecla = true
			keyButton.Text = tecla and primeiro or ""
			atualizandoTextoTecla = false
			if tecla then definirTecla(tecla) end
		end)
		keyButton.FocusLost:Connect(function()
			atualizarTextoTecla()
		end)
	elseif keyButton and keyButton:IsA("TextButton") then
		local inicial = obterTecla(keyButton.Text)
		if inicial then definirTecla(inicial) end
		keyButton.Activated:Connect(function()
			capturando = true
			keyButton.Text = "..."
		end)
	else
		warn("[HPX BONES] Campo keybuton/keybutton n�o encontrado.")
	end
	
	boneButton.Activated:Connect(function()
		if capturando then return end
		alternar()
	end)
	
	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if capturando and input.UserInputType == Enum.UserInputType.Keyboard then
			capturando = false
			local codigo = obterTecla(nomeVisivel(input.KeyCode))
			if codigo then definirTecla(codigo) else atualizarTextoTecla() end
			return
		end
		if gameProcessed or UserInputService:GetFocusedTextBox() then return end
		if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == TECLA_ATIVAR then
			alternar()
		end
	end)
	
	boneButton.Destroying:Connect(function()
		if ativo then
			ativo = false
			geracao += 1
		end
		if TECLA_ATIVAR and _G.HPX_Atalhos[nomeVisivel(TECLA_ATIVAR)] == OWNER then
			_G.HPX_Atalhos[nomeVisivel(TECLA_ATIVAR)] = nil
		end
	end)
	
	atualizarTextoTecla()
	atualizarBotao()
	print("[HPX BONES] Painel conectado. Use BoneButton e defina a tecla no campo.")
	
end
