	}
	
	local spawnOrder = {}
	local spawnIndex = 1
	
	local function getCharacter()
		local char = player.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local root = char and char:FindFirstChild("HumanoidRootPart")
	
		if char and hum and root
			and hum.Health > 0
			and not root.Anchored
			and not hum.Sit
			and not hum.SeatPart then
			return char, hum, root
		end
	end
	
	local function getFolder()
		if folderInstance and folderInstance.Parent == workspace and folderInstance.Name == FOLDER_NAME then
			return folderInstance
		end
		return workspace:FindFirstChild(FOLDER_NAME)
	end
	
	local function belongsToFolder(obj)
		local folder = getFolder()
	
		if not folder or not obj then
			return false
		end
	
		if obj == folder then
			return true
		end
	
		return obj:IsDescendantOf(folder)
	end
	
	local function getPotionPart(obj)
		if obj:IsA("BasePart") then
			return obj
		end
	
		local part = obj:FindFirstChild("Potion", true)
	
		if part and part:IsA("BasePart") then
			return part
		end
	
		if obj:IsA("Model") and obj.PrimaryPart then
			return obj.PrimaryPart
		end
	
		return obj:FindFirstChildWhichIsA("BasePart", true)
	end
	
	local function getPotionPosition(obj)
		local part = getPotionPart(obj)
	
		if part and part.Parent then
			return part.Position
		end
	
		if obj:IsA("Model") then
			return obj:GetPivot().Position
		end
	
		return nil
	end
	
	local function watchFolder()
		local folder = getFolder()
		if folder == folderInstance then
			return
		end
	
		if folderAddedConnection then folderAddedConnection:Disconnect(); folderAddedConnection = nil end
		if folderRemovingConnection then folderRemovingConnection:Disconnect(); folderRemovingConnection = nil end
		folderInstance = folder
		newPotion = nil
		table.clear(potionObjects)
		table.clear(potionIndices)
		if not folder then
			return
		end
	
		-- Guarda modelos e pecas para tambem reconhecer objetos renomeados depois.
		local function onAdded(obj)
			if potionIndices[obj] or not (obj:IsA("Model") or obj:IsA("BasePart")) then
				return
			end
			potionObjects[#potionObjects + 1] = obj
			potionIndices[obj] = #potionObjects
			if obj.Name == POTION_NAME then
				newPotion = obj
			end
		end
		local function onRemoving(obj)
			local index = potionIndices[obj]
			if not index then
				return
			end
			local last = potionObjects[#potionObjects]
			potionObjects[index] = last
			potionIndices[last] = index
			potionObjects[#potionObjects] = nil
			potionIndices[obj] = nil
			failed[obj] = nil
			if newPotion == obj then
				newPotion = nil
			end
		end
	
		folderAddedConnection = folder.DescendantAdded:Connect(onAdded)
		folderRemovingConnection = folder.DescendantRemoving:Connect(onRemoving)
		for _, obj in ipairs(folder:GetDescendants()) do
			onAdded(obj)
		end
	end
	
	-- Mesmo metodo de deslocamento do script de grimorios.
	local function move(char, root, position)
		if player.Character ~= char or not root.Parent then
			return false
		end
	
		char:PivotTo(
			CFrame.new(position - root.Position) * char:GetPivot()
		)
	
		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
	
		return true
	end
	
	local function getCharacterHeight(hum, root, char)
		local y = hum.HipHeight + root.Size.Y * 0.5 + 0.35
	
		if hum.RigType == Enum.HumanoidRigType.R6 then
			local leg = char:FindFirstChild("Left Leg")
	
			if leg then
				y += leg.Size.Y
			end
		end
	
		return math.max(3, y)
	end
	
	local function teleportToPotion(obj)
		local char, hum, root = getCharacter()
	
		if not char or not obj or not obj.Parent then
			return false
		end
	
		local position = getPotionPosition(obj)
	
		if not position then
			return false
		end
	
		-- Tenta chegar ao centro da po��o usando a altura do personagem.
		local destination = position + Vector3.new(
			0,
			getCharacterHeight(hum, root, char),
			0
		)
	
		return move(char, root, destination)
	end
	
	local function shuffleSpawns()
		spawnOrder = {}
	
		for i = 1, #INITIAL_SPAWNS do
			spawnOrder[i] = i
		end
	
		for i = #spawnOrder, 2, -1 do
			local j = random:NextInteger(1, i)
			spawnOrder[i], spawnOrder[j] =
				spawnOrder[j], spawnOrder[i]
		end
	
		spawnIndex = 1
	end
	
	local function teleportToSpawn()
		local char, hum, root = getCharacter()
	
		if not char then
			task.wait(0.5)
			return
		end
	
		if #spawnOrder == 0 or spawnIndex > #spawnOrder then
			shuffleSpawns()
		end
	
		local index = spawnOrder[spawnIndex]
		spawnIndex += 1
	
		local position = INITIAL_SPAWNS[index]
	
		-- Tenta encontrar o terreno pr�ximo � coordenada.
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
	
		local exclusions = {char}
		local folder = getFolder()
	
		if folder then
			table.insert(exclusions, folder)
		end
	
		params.FilterDescendantsInstances = exclusions
		params.IgnoreWater = false
	
		local hit = workspace:Raycast(
			position + Vector3.new(0, 25, 0),
			Vector3.new(0, -65, 0),
			params
		)
	
		local destination
	
		if hit
			and hit.Normal.Y > 0.55
			and hit.Material ~= Enum.Material.Water
			and math.abs(hit.Position.Y - position.Y) < 15 then
	
			destination = hit.Position
				+ Vector3.new(0, getCharacterHeight(hum, root, char), 0)
		else
			-- Igual ao script original: usa o Y salvo se n�o encontrar ch�o.
			destination = position + Vector3.new(0, 2.5, 0)
		end
	
		move(char, root, destination)
	end
	
	-- ------------------------------------------------------------------
	-- Exploracao do mapa em partes: cria um grid de pontos sobre a area
	-- do mapa para forcar o carregamento (streaming) das regioes.
	-- ------------------------------------------------------------------
	local gridPoints = {}
	local gridIndex = 1
	
	local function getMapBounds()
		local map = workspace:FindFirstChild("Map")
	
		if map and map:IsA("Model") then
			local cf, size = map:GetBoundingBox()
	
			if size.X > 0 and size.Z > 0 then
				return cf.Position - size / 2, cf.Position + size / 2
			end
		end
	
		-- Fallback: usa a area conhecida dos spawns.
		local minX, maxX, minZ, maxZ = math.huge, -math.huge, math.huge, -math.huge
	
		for _, p in ipairs(INITIAL_SPAWNS) do
			minX = math.min(minX, p.X)
			maxX = math.max(maxX, p.X)
			minZ = math.min(minZ, p.Z)
			maxZ = math.max(maxZ, p.Z)
		end
	
		return Vector3.new(minX, 0, minZ), Vector3.new(maxX, 0, maxZ)
	end
	
	local function buildGrid()
		gridPoints = {}
		gridIndex = 1
	
		local min, max = getMapBounds()
		local step = MAP_STEP
		local z = min.Z + step / 2
	
		while z <= max.Z do
			local x = min.X + step / 2
	
			while x <= max.X do
				gridPoints[#gridPoints + 1] = Vector3.new(x, 0, z)
				x += step
			end
	
			z += step
		end
	
		-- Shuffle para nao ficar sempre na mesma ordem.
		for i = #gridPoints, 2, -1 do
			local j = random:NextInteger(1, i)
			gridPoints[i], gridPoints[j] = gridPoints[j], gridPoints[i]
		end
	
	end
	
	local function teleportToGridPoint()
		local char, hum, root = getCharacter()
	
		if not char then
			return false
		end
	
		if #gridPoints == 0 then
			buildGrid()
		end
	
		if gridIndex > #gridPoints then
			gridIndex = 1
		end
	
		local point = gridPoints[gridIndex]
		if not point then
			return false
		end
		gridIndex += 1
	
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
	
		local exclusions = {char}
		local folder = getFolder()
	
		if folder then
			table.insert(exclusions, folder)
		end
	
		params.FilterDescendantsInstances = exclusions
		params.IgnoreWater = false
	
		local hit = workspace:Raycast(
			point + Vector3.new(0, MAP_RAY_UP, 0),
			Vector3.new(0, -MAP_RAY_DOWN, 0),
			params
		)
	
		local destination
	
		if hit and hit.Normal.Y > 0.4 and hit.Material ~= Enum.Material.Water then
			destination = hit.Position + Vector3.new(0, getCharacterHeight(hum, root, char), 0)
		else
			destination = point + Vector3.new(0, 40, 0)
		end
	
		move(char, root, destination)
	
		return true
	end
	
	local function scanNearby()
		local _, _, root = getCharacter()
	
		if not root then
			return nil
		end
	
		local nearest
		local fallback
		local nearestDistance = SCAN_RADIUS * SCAN_RADIUS
		local rootPosition = root.Position
		watchFolder()
		for _, obj in ipairs(potionObjects) do
			if obj.Name == POTION_NAME and not failed[obj] then
				local position = getPotionPosition(obj)
				if position then
					local offset = position - rootPosition
					local distance = offset:Dot(offset)
	
					-- Fallback: qualquer pocao viva, mesmo fora do raio.
					if not fallback then
						fallback = obj
					end
	
					if distance <= nearestDistance then
						nearest = obj
						nearestDistance = distance
					end
				end
			end
		end
	
		return nearest or fallback
	end
	
	local function collectPotion(obj, token)
		if not enabled or token ~= generation then
			return false
		end
		if not belongsToFolder(obj) then
			return true
		end
	
		if not teleportToPotion(obj) then
			return false
		end
	
		-- Segura o ProximityPrompt para efetivamente coletar.
		local part = getPotionPart(obj)
		local prompt = obj:FindFirstChildWhichIsA("ProximityPrompt", true)
	
		if not prompt and part then
			prompt = part:FindFirstChildWhichIsA("ProximityPrompt", true)
		end
	
		if prompt then
			local hold = math.max(0.1, (prompt.HoldDuration or 0) + 0.15)
			local holdState = { Prompt = prompt }
			activeHold = holdState
			pcall(function() prompt:InputHoldBegin() end)
			task.wait(hold)
			if activeHold == holdState then
				releasePrompt()
			end
		end
	
		local started = os.clock()
	
		-- Espera a coleta acontecer antes de buscar outra po��o.
		while enabled and token == generation and belongsToFolder(obj) do
			if os.clock() - started >= COLLECT_TIMEOUT then
				break
			end
	
			task.wait(0.1)
		end
	
		if not enabled or token ~= generation then
			return false
		end
		if not belongsToFolder(obj) then
			failed[obj] = nil
			return true
		end
	
		-- N�o marca como coletada: o item ainda est� na pasta.
		failed[obj] = os.clock() + RETRY_DELAY
	
		return false
	end
	
	local function run(token)
		while enabled and token == generation do
			-- Remove bloqueios de tentativas que j� expiraram.
			local now = os.clock()
			for obj, retryAt in pairs(failed) do
				if not obj.Parent or now >= retryAt then
					failed[obj] = nil
				end
			end
	
			-- Prioridade m�xima: po��o recem-carregada na pasta.
			local potion = newPotion
	
			if potion and (potion.Name ~= POTION_NAME or not belongsToFolder(potion)) then
				newPotion = nil
				potion = nil
			end
	
			if not potion then
				potion = scanNearby()
			end
	
			if potion then
				newPotion = nil
				collectPotion(potion, token)
				if not enabled or token ~= generation then
					break
				end
				refreshButton()
				task.wait(0.2)
			else
				-- Alterna entre pontos conhecidos e grid do mapa para varrer tudo.
				if visitsSinceGrid >= GRID_VISITS_BEFORE_SPAWN then
					visitsSinceGrid = 0
					teleportToGridPoint()
				else
					visitsSinceGrid += 1
					teleportToSpawn()
				end
	
				task.wait(SCAN_SECONDS)
	
				-- Escaneia de novo logo ap�s chegar ao ponto (raio amplo).
				if enabled and token == generation then
					local found = scanNearby()
	
					if found then
						collectPotion(found, token)
					end
				end
	
				if not enabled or token ~= generation then
					break
				end
				refreshButton()
			end
	
			task.wait(0.1)
		end
	end
	
	-- ------------------------------------------------------------------
	-- Watcher da pasta: detecta PotionTemplate assim que o streaming
	-- carrega uma nova regiao do mapa.
	-- ------------------------------------------------------------------
	connect(workspace.ChildAdded, function(child)
		if child.Name == FOLDER_NAME then
			watchFolder()
		end
	end)
	connect(workspace.ChildRemoved, function(child)
		if child == folderInstance then
			watchFolder()
		end
	end)
	
	watchFolder()
	
	-- ------------------------------------------------------------------
	-- Botao Lobo e atalho de teclado
	-- ------------------------------------------------------------------
	local corAtiva = Color3.fromRGB(0, 170, 0)
	
	local digitKeys = {
		Zero = "0", One = "1", Two = "2", Three = "3", Four = "4",
		Five = "5", Six = "6", Seven = "7", Eight = "8", Nine = "9",
	}
	
	local function displayKeyName(keyCode)
		return digitKeys[keyCode.Name] or keyCode.Name
	end
	
	local function getValidKey(keyCode)
		if not keyCode or keyCode == Enum.KeyCode.Unknown then
			return false
		end
	
		local name = keyCode.Name
		return (#name == 1 and name:match("^[A-Z0-9]$") ~= nil) or digitKeys[name] ~= nil
	end
	
	local function updateHotkeyText()
		if not keyTarget or not keyTarget:IsA("TextLabel")
			and not keyTarget:IsA("TextButton")
			and not keyTarget:IsA("TextBox") then
			return
		end
	
		keyTarget.Text = hotkey and displayKeyName(hotkey) or "-"
	end
	
	local function updateButton()
		if loboButton:IsA("GuiButton") and originalButtonColor then
			loboButton.BackgroundColor3 = enabled and corAtiva or originalButtonColor
		end
	end
	
	refreshButton = updateButton
	
	local function showKeyUsed()
		if not keyTarget then
			return
		end
	
		noticeNumber += 1
		local thisNotice = noticeNumber
		keyTarget.Text = "USADA"
	
		task.delay(1.2, function()
			if thisNotice == noticeNumber and keyTarget.Parent then
				updateHotkeyText()
			end
		end)
	end
	
	local function setHotkey(keyCode)
		if not getValidKey(keyCode) then
			return false
		end
	
		local keyName = keyCode.Name
		local owner = _G.HPX_Atalhos[keyName]
	
		if owner and owner ~= OWNER then
			choosingKey = false
			showKeyUsed()
			return false
		end
	
		if hotkey and _G.HPX_Atalhos[hotkey.Name] == OWNER then
			_G.HPX_Atalhos[hotkey.Name] = nil
		end
	
		hotkey = keyCode
		_G.HPX_Atalhos[keyName] = OWNER
		choosingKey = false
		noticeNumber += 1
		updateHotkeyText()
	
		if keyTarget and keyTarget:IsA("TextBox") and keyTarget:IsFocused() then
			keyTarget:ReleaseFocus()
		end
	
		return true
	end
	
	local function startChoosingKey()
		if not keyTarget then
			return
		end
	
		choosingKey = true
