		Size = UDim2.new(0.72, 0, 0.38, 0),
		BackgroundTransparency = 1,
		Font = Enum.Font.GothamSemibold,
		Text = "DisplayName",
		TextColor3 = Color3.fromRGB(244, 246, 250),
		TextSize = 15,
		TextScaled = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local nomeTemplate = ensureTemplatePart("Nome", "TextLabel", {
		Position = UDim2.new(0.24, 0, 0.55, 0),
		Size = UDim2.new(0.42, 0, 0.28, 0),
		BackgroundTransparency = 1,
		Font = Enum.Font.Gotham,
		Text = "Username",
		TextColor3 = Color3.fromRGB(169, 181, 203),
		TextSize = 11,
		TextScaled = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local cargoTemplate = ensureTemplatePart("Cargo", "TextLabel", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(0.96, 0, 0.69, 0),
		Size = UDim2.new(0.28, 0, 0.34, 0),
		BackgroundColor3 = Color3.fromRGB(54, 64, 84),
		BorderSizePixel = 0,
		Font = Enum.Font.GothamBold,
		Text = "Membro",
		TextColor3 = Color3.fromRGB(203, 212, 228),
		TextSize = 9,
		TextScaled = true,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local cargoCorner = cargoTemplate:FindFirstChildOfClass("UICorner")
	if not cargoCorner then
		cargoCorner = make("UICorner", "CargoCorner", cargoTemplate)
	end
	cargoCorner.CornerRadius = UDim.new(0, 6)
	
	local textSizeLimits = {
		[apelidoTemplate] = { MinTextSize = 8, MaxTextSize = 15 },
		[nomeTemplate] = { MinTextSize = 7, MaxTextSize = 11 },
		[cargoTemplate] = { MinTextSize = 7, MaxTextSize = 10 },
	}
	for label, limits in pairs(textSizeLimits) do
		local constraint = label:FindFirstChildOfClass("UITextSizeConstraint")
		if not constraint then
			constraint = make("UITextSizeConstraint", "TextSizeLimit", label)
		end
		constraint.MinTextSize = limits.MinTextSize
		constraint.MaxTextSize = limits.MaxTextSize
	end
	
	local templateCorner = bannerTemplate:FindFirstChildOfClass("UICorner")
	if not templateCorner then
		templateCorner = make("UICorner", "CardCorner", bannerTemplate)
	end
	templateCorner.CornerRadius = UDim.new(0, 10)
	local templateStroke = bannerTemplate:FindFirstChildOfClass("UIStroke")
	if not templateStroke then
		templateStroke = make("UIStroke", "CardStroke", bannerTemplate)
	end
	templateStroke.Color = DEFAULT_STROKE
	templateStroke.Thickness = 1
	templateStroke.Transparency = 0.15
	local templateMark = bannerTemplate:FindFirstChild("SelectedMark")
	if not templateMark then
		templateMark = make("Frame", "SelectedMark", bannerTemplate)
	end
	templateMark.Position = UDim2.new(0, 0, 0.15, 0)
	templateMark.Size = UDim2.new(0, 3, 0.7, 0)
	templateMark.BackgroundColor3 = SELECTED_STROKE
	templateMark.BorderSizePixel = 0
	templateMark.Visible = false
	local templateMarkCorner = templateMark:FindFirstChildOfClass("UICorner")
	if not templateMarkCorner then
		templateMarkCorner = make("UICorner", "Corner", templateMark)
	end
	templateMarkCorner.CornerRadius = UDim.new(1, 0)
	
	local grid
	for _, child in ipairs(lista:GetChildren()) do
		if child:IsA("UIGridLayout") then
			if grid then
				child:Destroy()
			else
				grid = child
			end
		elseif child:IsA("UIListLayout") then
			child:Destroy()
		elseif child:IsA("GuiButton") and (
			child.Name == "Banner"
				or child:GetAttribute("PlayerCard")
				or (child:FindFirstChild("Apelido") and child:FindFirstChild("Nome"))
			) then
			child:Destroy()
		end
	end
	
	if not grid then
		grid = make("UIGridLayout", "PlayerGrid", lista)
	end
	grid.CellSize = DEFAULT_CELL_SIZE
	grid.CellPadding = DEFAULT_CELL_PADDING
	grid.FillDirection = Enum.FillDirection.Horizontal
	grid.FillDirectionMaxCells = 2
	grid.SortOrder = Enum.SortOrder.LayoutOrder
	
	local cmdsFolder = container:FindFirstChild("Cmds")
	if not cmdsFolder then
		cmdsFolder = make("Folder", "Cmds", container)
	end
	
	local selectedValue = cmdsFolder:FindFirstChild("PlayerSelecionado")
	if selectedValue and not selectedValue:IsA("StringValue") then
		selectedValue:Destroy()
		selectedValue = nil
	end
	if not selectedValue then
		selectedValue = make("StringValue", "PlayerSelecionado", cmdsFolder, { Value = "" })
	end
	
	local selectedPlayer = nil
	local cardsByPlayer = {}
	local roleByPlayer = {}
	local friendByPlayer = {}
	local connectionsByPlayer = {}
	local running = true
	local creatorGroupId = game.CreatorType == Enum.CreatorType.Group and game.CreatorId or nil
	local creatorGroupOwnerId = nil
	local alertRolesByPlayer = {}
	local alertQueue = {}
	local processingAlerts = false
	local notificationGui = nil
	local notificationSound = nil
	
	local function alertTween(object, properties, duration, style, direction)
		local tween = TweenService:Create(object, TweenInfo.new(
			duration, style or Enum.EasingStyle.Quint, direction or Enum.EasingDirection.Out
			), properties)
		tween:Play()
		return tween
	end
	
	local function getNotificationGui()
		if notificationGui and notificationGui.Parent then
			return notificationGui
		end
		local panelGui = container:FindFirstAncestorOfClass("ScreenGui")
		local guiParent = panelGui and panelGui.Parent or localPlayer:FindFirstChildOfClass("PlayerGui")
		if not guiParent then
			return nil
		end
		-- A separate ScreenGui keeps alerts visible when the player panel is closed.
		notificationGui = make("ScreenGui", "HPXPlayerAlerts", guiParent, {
			DisplayOrder = math.max(200, panelGui and panelGui.DisplayOrder + 1 or 200),
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		})
		return notificationGui
	end
	
	local function playAlertSound(role)
		pcall(function()
			if not notificationSound or not notificationSound.Parent then
				notificationSound = make("Sound", "HPXPlayerAlertSound", SoundService, {
					SoundId = ALERT_SOUND_ID,
					Volume = 0.65,
					Looped = false,
				})
			end
			local sound = notificationSound
			sound:Stop()
			sound.SoundId = role == "Amigo" and FRIEND_ALERT_SOUND_ID or ALERT_SOUND_ID
			sound:Play()
			if role ~= "Amigo" then
				task.delay(1.5, function()
					if running and notificationSound == sound and sound.Parent then
						sound:Stop()
					end
				end)
			end
		end)
	end
	
	local function showPlayerAlert(player, role, joined)
		local gui = getNotificationGui()
		if not gui then
			return
		end
		local isFriendAlert = role == "Amigo"
		local color = isFriendAlert and FRIEND_COLOR
			or role == "Dono" and Color3.fromRGB(255, 201, 94)
			or role == "Admin" and Color3.fromRGB(255, 151, 101)
			or Color3.fromRGB(105, 153, 255)
		local outlineColor = isFriendAlert and FRIEND_COLOR or Color3.fromRGB(0, 0, 255)
		local title = isFriendAlert and (joined and "Amigo entrou" or "Amigo no servidor")
			or (role == "Membro" and "Jogador entrou" or role .. " detectado")
		local toast = make("CanvasGroup", "PlayerAlert", gui, {
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, 460, 0, 26),
			Size = UDim2.new(1, -52, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundColor3 = isFriendAlert and Color3.fromRGB(13, 40, 29) or Color3.fromRGB(10, 15, 30),
			BackgroundTransparency = 0.08,
			GroupTransparency = 1,
			BorderSizePixel = 0,
		})
		make("UISizeConstraint", "WidthLimit", toast, { MaxSize = Vector2.new(430, math.huge) })
		make("UICorner", "Corner", toast, { CornerRadius = UDim.new(0, 18) })
		local outline = make("UIStroke", "Outline", toast, {
			Color = Color3.new(1, 1, 1), Transparency = 0.3, Thickness = 1.3,
		})
		make("UIGradient", "OutlineGradient", outline, {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, outlineColor),
				ColorSequenceKeypoint.new(0.5, Color3.new(1, 1, 1)),
				ColorSequenceKeypoint.new(1, outlineColor),
			}),
		})
		local icon = make("Frame", "AlertIcon", toast, {
			Size = UDim2.fromOffset(34, 34), Position = UDim2.fromOffset(14, 12),
			BackgroundColor3 = color, BackgroundTransparency = 0.78, BorderSizePixel = 0,
		})
		make("UICorner", "Corner", icon, { CornerRadius = UDim.new(1, 0) })
		make("UIStroke", "Outline", icon, { Color = color, Transparency = 0.35, Thickness = 1.3 })
		make("TextLabel", "Glyph", icon, {
			Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
			Text = "!", TextColor3 = color, Font = Enum.Font.GothamBold, TextSize = 24,
		})
		local content = make("Frame", "Content", toast, {
			Position = UDim2.fromOffset(60, 10), Size = UDim2.new(1, -76, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
		})
		make("UIListLayout", "Layout", content, {
			SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4),
		})
		make("TextLabel", "Title", content, {
			Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = 1,
			Text = title,
			TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 16,
			TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
		})
		make("TextLabel", "Message", content, {
			Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1, LayoutOrder = 2,
			Text = player.DisplayName .. " (@" .. player.Name .. ") "
				.. (joined and "entrou no servidor." or "esta no servidor."),
			TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.Gotham, TextSize = 13,
			TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
		})
		make("Frame", "Spacer", content, {
			Size = UDim2.new(1, 0, 0, 4), BackgroundTransparency = 1, LayoutOrder = 3,
		})
		local track = make("Frame", "ProgressTrack", content, {
			Size = UDim2.new(1, 0, 0, 3), BackgroundColor3 = Color3.fromRGB(54, 54, 60),
			BackgroundTransparency = 0.85, BorderSizePixel = 0, LayoutOrder = 4,
		})
		make("UICorner", "Corner", track, { CornerRadius = UDim.new(1, 0) })
		local progress = make("Frame", "Progress", track, {
			Size = UDim2.fromScale(1, 1), BackgroundColor3 = color, BorderSizePixel = 0,
		})
		make("UICorner", "Corner", progress, { CornerRadius = UDim.new(1, 0) })
		make("Frame", "BottomPadding", content, {
			Size = UDim2.new(1, 0, 0, 8), BackgroundTransparency = 1, LayoutOrder = 5,
		})
		alertTween(toast, { Position = UDim2.new(1, -26, 0, 26), GroupTransparency = 0 }, 0.42, Enum.EasingStyle.Back)
		alertTween(progress, { Size = UDim2.fromScale(0, 1) }, ALERT_DURATION, Enum.EasingStyle.Linear)
		playAlertSound(role)
		task.wait(ALERT_DURATION)
		if not running or not toast.Parent then
			return
		end
		alertTween(toast, { Position = UDim2.new(1, 460, 0, 26), GroupTransparency = 1 }, 0.32,
		Enum.EasingStyle.Quint, Enum.EasingDirection.In)
		task.wait(0.38)
		toast:Destroy()
	end
	
	local function enqueuePlayerAlert(player, role, joined)
		table.insert(alertQueue, { Player = player, Role = role, Joined = joined })
		if processingAlerts then
			return
		end
		processingAlerts = true
		task.spawn(function()
			while running and #alertQueue > 0 do
				local entry = table.remove(alertQueue, 1)
				local current = entry.Role == "Amigo" and friendByPlayer[entry.Player] == true
					or roleByPlayer[entry.Player] == entry.Role
				if entry.Player.Parent == Players and current then
					pcall(showPlayerAlert, entry.Player, entry.Role, entry.Joined)
				end
			end
			processingAlerts = false
		end)
	end
	
	local function notifyPlayerRole(player, role)
		local previousRole = alertRolesByPlayer[player]
		alertRolesByPlayer[player] = role
		if player == localPlayer or previousRole == role or (role == "Membro" and not ALERT_MEMBERS) then
			return
		end
		enqueuePlayerAlert(player, role)
	end
	
	local function setCardRole(badge, role)
		if not badge or not badge.Parent then
			return
		end
		badge.Text = role
		if role == "Dono" then
			badge.BackgroundColor3 = Color3.fromRGB(104, 79, 35)
			badge.TextColor3 = Color3.fromRGB(255, 224, 150)
		elseif role == "Admin" then
			badge.BackgroundColor3 = Color3.fromRGB(91, 57, 48)
			badge.TextColor3 = Color3.fromRGB(255, 190, 160)
		elseif role == "Amigo" then
			badge.BackgroundColor3 = Color3.fromRGB(29, 75, 49)
			badge.TextColor3 = FRIEND_COLOR
		else
			badge.BackgroundColor3 = Color3.fromRGB(54, 64, 84)
			badge.TextColor3 = Color3.fromRGB(203, 212, 228)
		end
	end
	
	local function updateCardBadge(player, card)
		local role = roleByPlayer[player] or "Membro"
		if role == "Membro" and friendByPlayer[player] then
			role = "Amigo"
		end
		setCardRole(card:FindFirstChild("Cargo", true), role)
	end
	
	local function sortPlayerCards()
		local rolePriority = { Dono = 1, Admin = 2, Membro = 3 }
		local entries = {}
		for player, card in pairs(cardsByPlayer) do
			table.insert(entries, {
				Player = player,
				Card = card,
				IsFriend = friendByPlayer[player] == true,
				Priority = rolePriority[roleByPlayer[player]] or 3,
			})
		end
		table.sort(entries, function(a, b)
			if a.IsFriend ~= b.IsFriend then
				return a.IsFriend
			end
			if a.Priority ~= b.Priority then
				return a.Priority < b.Priority
			end
			local nameA = string.lower(a.Player.DisplayName .. a.Player.Name)
			local nameB = string.lower(b.Player.DisplayName .. b.Player.Name)
			if nameA ~= nameB then
				return nameA < nameB
			end
			return a.Player.UserId < b.Player.UserId
		end)
		for index, entry in ipairs(entries) do
			entry.Card.LayoutOrder = index
		end
	end
	
	local function updateFriendship(player, card, joined)
		if player == localPlayer then
			return
		end
		task.spawn(function()
			local success, isFriend = pcall(function()
				return localPlayer:IsFriendsWithAsync(player.UserId)
			end)
			if not success or not running or cardsByPlayer[player] ~= card or not card.Parent then
				return
			end
			local wasFriend = friendByPlayer[player]
			friendByPlayer[player] = isFriend == true
			updateCardBadge(player, card)
			sortPlayerCards()
			if isFriend and not wasFriend then
				enqueuePlayerAlert(player, "Amigo", joined)
			end
		end)
	end
	
	local function updateRole(player, card)
		if not running then
			return
		end
		local badge = card and card:FindFirstChild("Cargo")
		if not badge then
			return
		end
	
		task.spawn(function()
			local groupRank = 0
			local groupRoles = {}
			if creatorGroupId then
				local rolesOK, groupData = pcall(function()
					return GroupService:GetRolesInGroupAsync(player.UserId, creatorGroupId)
				end)
				if rolesOK and type(groupData) == "table" then
					for _, role in ipairs(groupData.Roles or {}) do
						local roleName = tostring(role.Name or "")
						local roleRank = tonumber(role.Rank) or 0
						table.insert(groupRoles, roleName)
						groupRank = math.max(groupRank, roleRank)
					end
				end
			end
	
			local customRole = tostring(player:GetAttribute("ExperienceRole") or player:GetAttribute("Role") or "")
			local roleText = string.lower(table.concat(groupRoles, " ") .. " " .. customRole)
			local isOwner = (game.CreatorType == Enum.CreatorType.User and player.UserId == game.CreatorId)
				or (creatorGroupOwnerId ~= nil and player.UserId == creatorGroupOwnerId)
				or (creatorGroupId ~= nil and groupRank >= 255)
				or roleText:find("owner", 1, true) ~= nil
				or roleText:find("dono", 1, true) ~= nil
	
			local hasAdminRole = roleText:find("admin", 1, true) ~= nil
				or roleText:find("adm", 1, true) ~= nil
				or roleText:find("moderator", 1, true) ~= nil
				or roleText:find("moderador", 1, true) ~= nil
			local isAdmin = ADMIN_USER_IDS[player.UserId] == true
				or player:GetAttribute("Admin") == true
				or player:GetAttribute("IsAdmin") == true
				or hasAdminRole
				or (creatorGroupId ~= nil and groupRank >= ADMIN_MIN_GROUP_RANK)
	
			if not running or cardsByPlayer[player] ~= card or not card.Parent then
				return
			end
			if isOwner then
				roleByPlayer[player] = "Dono"
			elseif isAdmin then
				roleByPlayer[player] = "Admin"
			else
				roleByPlayer[player] = "Membro"
			end
			updateCardBadge(player, card)
			sortPlayerCards()
			notifyPlayerRole(player, roleByPlayer[player])
		end)
	end
	
	local function applySelection(player)
		if selectedPlayer and cardsByPlayer[selectedPlayer] then
			local oldCard = cardsByPlayer[selectedPlayer]
			oldCard.BackgroundColor3 = DEFAULT_COLOR
			local oldStroke = oldCard:FindFirstChildOfClass("UIStroke")
			if oldStroke then
				oldStroke.Color = DEFAULT_STROKE
			end
			local oldMark = oldCard:FindFirstChild("SelectedMark")
			if oldMark then
				oldMark.Visible = false
			end
		end
	
		selectedPlayer = player
		if selectedPlayer and cardsByPlayer[selectedPlayer] then
			local newCard = cardsByPlayer[selectedPlayer]
			newCard.BackgroundColor3 = SELECTED_COLOR
			local newStroke = newCard:FindFirstChildOfClass("UIStroke")
			if newStroke then
				newStroke.Color = SELECTED_STROKE
			end
			local newMark = newCard:FindFirstChild("SelectedMark")
			if newMark then
				newMark.Visible = true
			end
			selectedValue.Value = selectedPlayer.Name
		else
			selectedPlayer = nil
			selectedValue.Value = ""
		end
	end
	
	local function addConnection(player, connection)
		connectionsByPlayer[player] = connectionsByPlayer[player] or {}
		table.insert(connectionsByPlayer[player], connection)
	end
	
	local function createPlayerCard(player, joined)
		if not running or cardsByPlayer[player] then
			return
		end
	
		local card = bannerTemplate:Clone()
		card.Name = player.Name
		card.BackgroundColor3 = DEFAULT_COLOR
		card.BorderSizePixel = 0
		card.AutoButtonColor = false
		if card:IsA("TextButton") then
			card.Text = ""
		end
		card.Visible = true
		card.LayoutOrder = player.UserId
		card.ClipsDescendants = true
		card:SetAttribute("PlayerCard", true)
		card:SetAttribute("PlayerUserId", player.UserId)
		local foto = card:FindFirstChild("Foto", true)
		local apelido = card:FindFirstChild("Apelido", true)
		local nome = card:FindFirstChild("Nome", true)
		local badge = card:FindFirstChild("Cargo", true)
		local stroke = card:FindFirstChildOfClass("UIStroke")
		if not stroke then
			stroke = make("UIStroke", "CardStroke", card, {
				Color = DEFAULT_STROKE,
				Thickness = 1,
				Transparency = 0.15,
			})
		end
		local selectedMark = card:FindFirstChild("SelectedMark")
		if not selectedMark then
			selectedMark = make("Frame", "SelectedMark", card, {
				Position = UDim2.new(0, 0, 0.15, 0),
				Size = UDim2.new(0, 3, 0.7, 0),
				BackgroundColor3 = SELECTED_STROKE,
				BorderSizePixel = 0,
				Visible = false,
			})
			make("UICorner", "Corner", selectedMark, { CornerRadius = UDim.new(1, 0) })
		end
		selectedMark.Visible = false
		if apelido then apelido.Text = player.DisplayName end
		if nome then nome.Text = player.Name end
		if foto then foto.Image = "" end
		setCardRole(badge, "Membro")
		card.Parent = lista
	
		cardsByPlayer[player] = card
		roleByPlayer[player] = "Membro"
		sortPlayerCards()
		addConnection(player, card.Activated:Connect(function()
			if selectedPlayer == player then
				applySelection(nil)
			else
				applySelection(player)
			end
		end))
		card.MouseEnter:Connect(function()
			if selectedPlayer ~= player then
				card.BackgroundColor3 = HOVER_COLOR
			end
		end)
		card.MouseLeave:Connect(function()
			if selectedPlayer ~= player then
				card.BackgroundColor3 = DEFAULT_COLOR
			end
		end)
	
		addConnection(player, player:GetPropertyChangedSignal("DisplayName"):Connect(function()
			if apelido.Parent then
				apelido.Text = player.DisplayName
			end
		end))
		addConnection(player, player:GetPropertyChangedSignal("Name"):Connect(function()
			if nome.Parent then
				nome.Text = player.Name
				card.Name = player.Name
			end
			if selectedPlayer == player then
				selectedValue.Value = player.Name
			end
		end))
		for _, attributeName in ipairs({ "Role", "ExperienceRole", "Admin", "IsAdmin" }) do
			addConnection(player, player:GetAttributeChangedSignal(attributeName):Connect(function()
				updateRole(player, card)
			end))
		end
	
		task.spawn(function()
			if not running then
				return
			end
			local success, image = pcall(function()
				return Players:GetUserThumbnailAsync(
					player.UserId,
					Enum.ThumbnailType.HeadShot,
					Enum.ThumbnailSize.Size150x150
				)
			end)
			if success and foto.Parent and cardsByPlayer[player] == card then
				foto.Image = image
			end
		end)
	
		updateRole(player, card)
		updateFriendship(player, card, joined)
	end
	
	local function removePlayerCard(player)
		if selectedPlayer == player then
			applySelection(nil)
		end
		local connections = connectionsByPlayer[player]
		if connections then
			for _, connection in ipairs(connections) do
				connection:Disconnect()
			end
			connectionsByPlayer[player] = nil
		end
		local card = cardsByPlayer[player]
		cardsByPlayer[player] = nil
		roleByPlayer[player] = nil
		friendByPlayer[player] = nil
		alertRolesByPlayer[player] = nil
		if card then
			card:Destroy()
		end
		sortPlayerCards()
	end
	
	local previousSelection = selectedValue.Value
	for _, player in ipairs(Players:GetPlayers()) do
		createPlayerCard(player)
		if player.Name == previousSelection then
			applySelection(player)
		end
	end
	if previousSelection ~= "" and not selectedPlayer then
		selectedValue.Value = ""
	end
	
	local playerAddedConnection = Players.PlayerAdded:Connect(function(player)
		createPlayerCard(player, true)
	end)
	local playerRemovingConnection = Players.PlayerRemoving:Connect(removePlayerCard)
	
	script.Destroying:Connect(function()
		running = false
		table.clear(alertQueue)
		if notificationGui then
			notificationGui:Destroy()
			notificationGui = nil
		end
		if notificationSound then
			notificationSound:Stop()
			notificationSound:Destroy()
			notificationSound = nil
		end
		playerAddedConnection:Disconnect()
		playerRemovingConnection:Disconnect()
		local playersToRemove = {}
		for player in pairs(cardsByPlayer) do
			table.insert(playersToRemove, player)
		end
		for _, player in ipairs(playersToRemove) do
			removePlayerCard(player)
		end
	end)
	
	if creatorGroupId then
		task.spawn(function()
			local success, info = pcall(function()
				return GroupService:GetGroupInfoAsync(creatorGroupId)
			end)
			if running and success and info and info.Owner then
				creatorGroupOwnerId = tonumber(info.Owner.Id)
				for player, card in pairs(cardsByPlayer) do
					updateRole(player, card)
				end
			end
		end)
	end
	
end
local function RDERA_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.stalker.SeachBox.seach
    local script = Instance.new("LocalScript")
    script.Name = "seach"
    script.Parent = Converted["_SeachBox"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local Players = game:GetService("Players")
	
	local seachBox = script.Parent
	
	-- Procurar pasta "Lista" no pai da SeachBox
	local container = script.Parent.Parent:FindFirstChild("Lista")
	if not container then
		container = Instance.new("Folder")
		container.Name = "Lista"
		container.Parent = script.Parent.Parent
	end
	
	-- Coletar itens que s�o clones reais de banner (t�m labels Apelido e/or Nome)
	local function coletarItens()
		local itens = {}
		for _, obj in ipairs(container:GetChildren()) do
			-- Pula o modelo template "Banner" original
			if obj.Name == "Banner" then
				continue
			end
	
			local hasApelido = obj:FindFirstChild("Apelido") and obj:FindFirstChild("Apelido"):IsA("TextLabel")
			local hasNome = obj:FindFirstChild("Nome") and obj:FindFirstChild("Nome"):IsA("TextLabel")
	
			if hasApelido or hasNome then
				table.insert(itens, obj)
			end
		end
		return itens
	end
	
	local function filtrar(luca)
		luca = (luca or ""):lower()
	
		for _, item in ipairs(coletarItens()) do
			local match = false
	
			local textoApelido = ""
	
			local apelido = item:FindFirstChild("Apelido")
	
			if apelido and apelido:IsA("TextLabel") then
				textoApelido = apelido.Text:lower()
			end
	
			-- Busca vazia mostra todo mundo
			if luca == "" then
				match = true
			else
				-- Busca APENAS no Apelido (substring)
				if string.find(textoApelido, luca, 1, true) then
					match = true
				end
			end
	
			item.Visible = match
		end
	end
	
	seachBox:GetPropertyChangedSignal("Text"):Connect(function()
		filtrar(seachBox.Text)
	end)
	
	-- Ao tirar o foco e limpar o campo, mostrar todos os itens novamente
	seachBox.FocusLost:Connect(function()
		if seachBox.Text == "" then
			for _, item in ipairs(coletarItens()) do
				item.Visible = true
			end
		end
	end)
	
end
local function DMYQRPC_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.stalker.Cmds.verButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_verButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local Players = game:GetService("Players")
	
	local localPlayer = Players.LocalPlayer
	local camera = workspace.CurrentCamera
	
	local stalkerFrame = script.Parent.Parent
	local verButton = script.Parent
	local playerSelecionadoValue = stalkerFrame:FindFirstChild("PlayerSelecionado")
	
	-- Salva a cor original do bot�o
	local corOriginal = verButton.BackgroundColor3
	
	if not playerSelecionadoValue then
		playerSelecionadoValue = Instance.new("StringValue")
		playerSelecionadoValue.Name = "PlayerSelecionado"
		playerSelecionadoValue.Parent = stalkerFrame
	end
	
	local vendoPlayer = false
	local playerAtual = nil
	
	local function getPlayerSelecionado()
		local nome = playerSelecionadoValue.Value
	
		if nome == "" then
			return nil
		end
	
		return Players:FindFirstChild(nome)
	end
	
	local function voltarCamera()
		local character = localPlayer.Character
		if not character then
			return
		end
	
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if humanoid then
			camera.CameraSubject = humanoid
		end
	end
	
	local function olharPlayer(player)
		if not player then
			return false
		end
	
		local character = player.Character
		if not character then
			return false
		end
	
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return false
		end
	
		playerAtual = player
		camera.CameraSubject = humanoid
	
		return true
	end
	
	local function ativarVer()
		local playerSelecionado = getPlayerSelecionado()
	
		if not playerSelecionado then
			warn("Nenhum player selecionado")
			return
		end
	
		if olharPlayer(playerSelecionado) then
			vendoPlayer = true
	
			-- Verde quando ativado
			verButton.BackgroundColor3 = Color3.fromRGB(0, 170, 0)
			verButton.Text = "Vendo"
		end
	end
	
	local function desativarVer()
		vendoPlayer = false
		playerAtual = nil
	
		voltarCamera()
	
		-- Volta exatamente para a cor que estava no Studio
		verButton.BackgroundColor3 = corOriginal
		verButton.Text = "Ver"
	end
	
	local function alternarVer()
		if vendoPlayer then
			desativarVer()
		else
			ativarVer()
		end
	end
	
	verButton.MouseButton1Click:Connect(alternarVer)
	
	playerSelecionadoValue:GetPropertyChangedSignal("Value"):Connect(function()
		if not vendoPlayer then
			return
		end
	
		local novoPlayer = getPlayerSelecionado()
	
		if novoPlayer then
			olharPlayer(novoPlayer)
		end
	end)
	
	Players.PlayerRemoving:Connect(function(player)
		if playerAtual == player then
			desativarVer()
		end
	end)
	
	localPlayer.CharacterAdded:Connect(function()
		if not vendoPlayer then
			task.wait(0.5)
			voltarCamera()
		end
	end)
end
local function RQMY_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.stalker.Cmds.syncButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_syncButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	
	local LocalPlayer = Players.LocalPlayer
	local button = script.Parent
	
	-- Salva a cor original do bot�o
	local corOriginal = button.BackgroundColor3
	
	local cmdsFolder = button.Parent
	local stalkerFrame = cmdsFolder.Parent
	local nameBox = stalkerFrame:FindFirstChildWhichIsA("TextBox", true)
	local playerSelecionadoValue = cmdsFolder:FindFirstChild("PlayerSelecionado")
	local flyState = cmdsFolder:FindFirstChild("FlyAtivo")
	
	if not playerSelecionadoValue then
		playerSelecionadoValue = Instance.new("StringValue")
		playerSelecionadoValue.Name = "PlayerSelecionado"
		playerSelecionadoValue.Parent = cmdsFolder
	end
	
	if not flyState then
		flyState = Instance.new("BoolValue")
		flyState.Name = "FlyAtivo"
		flyState.Value = false
		flyState.Parent = cmdsFolder
	end
	
	local syncing = false
	local syncConnection = nil
	local currentTrack = nil
	
	local function atualizarEstadoDoBotao()
		button.Active = not flyState.Value
		button.AutoButtonColor = not flyState.Value
	end
	
	local function getTargetPlayer()
		-- Prioridade 1: player selecionado na lista
		local nome = playerSelecionadoValue.Value
	
		if nome and nome ~= "" then
			local plr = Players:FindFirstChild(nome)
	
			if plr and plr ~= LocalPlayer then
				return plr
			end
		end
	
		-- Prioridade 2: caixa de pesquisa
		local text = string.lower(nameBox and nameBox.Text or "")
	
		if text == "" then
			return nil
		end
	
		for _, plr in ipairs(Players:GetPlayers()) do
			if plr ~= LocalPlayer then
				if string.find(string.lower(plr.Name), text)
					or string.find(string.lower(plr.DisplayName), text) then
	
					return plr
				end
			end
		end
	
		return nil
	end
	
	local function getHumanoid(player)
		local char = player.Character
	
		if not char then
			return nil
		end
	
		return char:FindFirstChildOfClass("Humanoid")
	end
	
	local function stopCurrent()
		if currentTrack then
			currentTrack:Stop()
			currentTrack = nil
		end
	end
	
	local function syncWithPlayer(targetPlayer)
		local myHum = getHumanoid(LocalPlayer)
		local targetHum = getHumanoid(targetPlayer)
	
		if not myHum or not targetHum then
			return
		end
	
		local targetTracks = targetHum:GetPlayingAnimationTracks()
		local chosenTrack = nil
	
		for _, track in ipairs(targetTracks) do
			local anim = track.Animation
	
			if anim and anim.AnimationId ~= "" then
				local animId = anim.AnimationId
	
				if not string.find(animId, "idle")
					and not string.find(animId, "walk")
					and not string.find(animId, "run")
					and not string.find(animId, "jump")
					and not string.find(animId, "fall") then
	
					chosenTrack = track
					break
				end
			end
		end
	
		if not chosenTrack then
			return
		end
	
		local animId = chosenTrack.Animation.AnimationId
	
		if currentTrack and currentTrack.Animation.AnimationId == animId then
			currentTrack.TimePosition = chosenTrack.TimePosition
			currentTrack:AdjustSpeed(chosenTrack.Speed)
			return
		end
	
		stopCurrent()
	
		local animator = myHum:FindFirstChildOfClass("Animator")
	
		if not animator then
			animator = Instance.new("Animator")
			animator.Parent = myHum
		end
	
		local anim = Instance.new("Animation")
		anim.AnimationId = animId
	
		local ok, track = pcall(function()
			return animator:LoadAnimation(anim)
		end)
	
		if ok and track then
			currentTrack = track
			currentTrack.Priority = Enum.AnimationPriority.Action
			currentTrack.Looped = true
			currentTrack:Play()
			currentTrack.TimePosition = chosenTrack.TimePosition
			currentTrack:AdjustSpeed(chosenTrack.Speed)
		end
	end
	
	local function stopSync()
		syncing = false
	
		button.Text = "sync emote"
	
		-- Volta para a cor original
		button.BackgroundColor3 = corOriginal
	
		if syncConnection then
			syncConnection:Disconnect()
			syncConnection = nil
		end
	
		stopCurrent()
	end
	
	flyState:GetPropertyChangedSignal("Value"):Connect(function()
		if flyState.Value and syncing then
			stopSync()
		end
	
		atualizarEstadoDoBotao()
	end)
	
	button.MouseButton1Click:Connect(function()
		if flyState.Value then
			return
		end
	
		local target = getTargetPlayer()
	
		if not target then
			warn("Nenhum player selecionado")
			return
		end
	
		syncing = not syncing
	
		if syncing then
			button.Text = "sync emote"
	
			-- Verde quando ativado
			button.BackgroundColor3 = Color3.fromRGB(0, 170, 0)
	
			syncConnection = RunService.Heartbeat:Connect(function()
				syncWithPlayer(target)
			end)
		else
			stopSync()
		end
	end)
	
	atualizarEstadoDoBotao()
	
	-- Para o sync automaticamente se o player sair
	Players.PlayerRemoving:Connect(function(player)
		if syncing and playerSelecionadoValue.Value == player.Name then
			stopSync()
		end
	end)
	
	-- Atualiza o target quando trocar o player selecionado
	playerSelecionadoValue:GetPropertyChangedSignal("Value"):Connect(function()
		if syncing then
			if syncConnection then
				syncConnection:Disconnect()
				syncConnection = nil
			end
	
			stopCurrent()
	
			local novoTarget = getTargetPlayer()
	
			if novoTarget then
				syncConnection = RunService.Heartbeat:Connect(function()
					syncWithPlayer(novoTarget)
				end)
			else
				stopSync()
			end
		end
	end)
end
