local function GJOS_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.stalker.Cmds.carinhoButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_carinhoButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	
	-- HPX | CARINHO V2
	-- LocalScript dentro de carinhoButton
	-- Procura PlayerSelecionado nas subpastas
	-- Senta na cabeca e acompanha o jogador
	
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	
	local LP = Players.LocalPlayer
	local botao = script.Parent
	
	local ID_ANIMACAO = "rbxassetid://75497695616518"
	local ALTURA_EXTRA = 0.15
	
	local corOriginal = botao.BackgroundColor3
	local corAtiva = Color3.fromRGB(0, 170, 0)
	
	local ativo = false
	local alvo = nil
	local conexao = nil
	local track = nil
	local animacao = nil
	
	local rootUsado = nil
	local anchoredOriginal = nil
	local autoRotateOriginal = nil
	local humanoidUsado = nil
	
	--------------------------------------------------
	-- LOCALIZAR SISTEMA STALKER
	--------------------------------------------------
	
	local stalker = botao:FindFirstAncestor("stalker")
	
	if not stalker then
		warn("[HPX CARINHO] ERRO: stalker nao encontrado!")
		return
	end
	
	-- Procura tamb�m dentro de Cmds e outras subpastas
	local playerSelecionado = stalker:FindFirstChild(
		"PlayerSelecionado", true
	)
	
	if not playerSelecionado then
		warn("[HPX CARINHO] PlayerSelecionado nao encontrado!")
		warn("[HPX CARINHO] Crie um StringValue chamado PlayerSelecionado dentro de stalker/Cmds.")
		return
	end
	
	if not playerSelecionado:IsA("StringValue")
		and not playerSelecionado:IsA("ObjectValue") then
	
		warn("[HPX CARINHO] PlayerSelecionado precisa ser StringValue ou ObjectValue!")
		return
	end
	
	print("[HPX CARINHO] PlayerSelecionado encontrado em:",
		playerSelecionado:GetFullName())
	
	--------------------------------------------------
	-- ESTADO VISUAL
	--------------------------------------------------
	
	local function atualizarBotao()
		botao.BackgroundColor3 =
			ativo and corAtiva or corOriginal
	end
	
	--------------------------------------------------
	-- BUSCAR JOGADOR SELECIONADO
	--------------------------------------------------
	
	local function encontrarAlvo()
		local valor = playerSelecionado.Value
	
		local jogador = nil
	
		if playerSelecionado:IsA("ObjectValue") then
			if typeof(valor) == "Instance"
				and valor:IsA("Player") then
				jogador = valor
			end
		else
			local nome = tostring(valor)
	
			if nome == "" then
				warn("[HPX CARINHO] Nenhum jogador selecionado!")
				return nil
			end
	
			-- Primeiro procura pelo Username exato
			jogador = Players:FindFirstChild(nome)
	
			-- Caso tenha sido salvo o DisplayName
			if not jogador then
				for _, p in ipairs(Players:GetPlayers()) do
					if p.DisplayName == nome then
						jogador = p
						break
					end
				end
			end
		end
	
		if not jogador then
			warn("[HPX CARINHO] Jogador nao encontrado:",
				tostring(valor))
			return nil
		end
	
		if jogador == LP then
			warn("[HPX CARINHO] Selecione outro jogador!")
			return nil
		end
	
		return jogador
	end
	
	--------------------------------------------------
	-- POSICIONAR SOBRE A CABECA
	--------------------------------------------------
	
	local function calcularDestino(cabeca)
		local meuChar = LP.Character
	
		if not meuChar then return nil end
	
		local meuHum = meuChar:FindFirstChildOfClass("Humanoid")
		local meuRoot = meuChar:FindFirstChild("HumanoidRootPart")
	
		if not meuHum or not meuRoot then
			return nil
		end
	
		-- Distancia entre o centro do personagem
		-- e a base dos pes
		local alturaPersonagem = math.max(
			1,
			meuHum.HipHeight
				+ meuRoot.Size.Y / 2
		)
	
		local altura =
			cabeca.Size.Y / 2
			+ alturaPersonagem
			+ ALTURA_EXTRA
	
		-- Usa a orientacao da cabeca no eixo horizontal
		local frente = cabeca.CFrame.LookVector
	
		local frenteHorizontal =
			Vector3.new(frente.X, 0, frente.Z)
	
		if frenteHorizontal.Magnitude < 0.01 then
			frenteHorizontal = Vector3.new(0, 0, -1)
		else
			frenteHorizontal = frenteHorizontal.Unit
		end
	
		local posicao = cabeca.Position
			+ Vector3.new(0, altura, 0)
	
		return CFrame.lookAt(
			posicao,
			posicao + frenteHorizontal
		)
	end
	
	--------------------------------------------------
	-- ANIMACAO
	--------------------------------------------------
	
	local function pararAnimacao()
		if track then
			pcall(function()
				track:Stop(0.15)
				track:Destroy()
			end)
			track = nil
		end
	
		if animacao then
			animacao:Destroy()
			animacao = nil
		end
	end
	
	local function tocarAnimacao()
		pararAnimacao()
	
		local char = LP.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
	
		if not hum then return end
	
		local animator = hum:FindFirstChildOfClass("Animator")
	
		if not animator then
			animator = Instance.new("Animator")
			animator.Parent = hum
		end
	
		animacao = Instance.new("Animation")
		animacao.AnimationId = ID_ANIMACAO
	
		local ok, resultado = pcall(function()
			return animator:LoadAnimation(animacao)
		end)
	
		if not ok then
			warn("[HPX CARINHO] Animacao nao carregou:", resultado)
			return
		end
	
		track = resultado
		track.Looped = true
		track.Priority = Enum.AnimationPriority.Action4
	
		track:Play(0.15)
	
		print("[HPX CARINHO] Emote iniciado:", ID_ANIMACAO)
	end
	
	--------------------------------------------------
	-- DESATIVAR
	--------------------------------------------------
	
	local function desativar()
		if not ativo then return end
	
		ativo = false
	
		if conexao then
			conexao:Disconnect()
			conexao = nil
		end
	
		pararAnimacao()
	
		if rootUsado and rootUsado.Parent then
			rootUsado.Anchored = anchoredOriginal == true
	
			rootUsado.AssemblyLinearVelocity = Vector3.zero
			rootUsado.AssemblyAngularVelocity = Vector3.zero
		end
	
		if humanoidUsado
			and humanoidUsado.Parent
			and autoRotateOriginal ~= nil then
	
			humanoidUsado.AutoRotate = autoRotateOriginal
		end
	
		rootUsado = nil
		humanoidUsado = nil
		anchoredOriginal = nil
		autoRotateOriginal = nil
		alvo = nil
	
		atualizarBotao()
	
		print("[HPX CARINHO] Desativado")
	end
	
	--------------------------------------------------
	-- ATIVAR
	--------------------------------------------------
	
	local function ativar()
		local jogador = encontrarAlvo()
	
		if not jogador then return end
	
		local meuChar = LP.Character
		local alvoChar = jogador.Character
	
		if not meuChar or not alvoChar then
			warn("[HPX CARINHO] Personagem nao carregado!")
			return
		end
	
		local root = meuChar:FindFirstChild("HumanoidRootPart")
		local hum = meuChar:FindFirstChildOfClass("Humanoid")
		local cabeca = alvoChar:FindFirstChild("Head")
	
		if not root or not hum or not cabeca then
			warn("[HPX CARINHO] Faltando Root, Humanoid ou Head!")
			return
		end
	
		if hum.Health <= 0 then return end
	
		local destino = calcularDestino(cabeca)
	
		if not destino then
			warn("[HPX CARINHO] Nao foi possivel calcular destino!")
			return
		end
	
		alvo = jogador
		ativo = true
	
		rootUsado = root
		humanoidUsado = hum
		anchoredOriginal = root.Anchored
		autoRotateOriginal = hum.AutoRotate
	
		-- Desativa a rotacao automatica
		hum.AutoRotate = false
	
		-- Mantem o personagem suspenso na posicao
		root.Anchored = true
	
		-- Primeiro teleporta, independente do emote
		meuChar:PivotTo(destino)
	
		atualizarBotao()
		tocarAnimacao()
	
		print("[HPX CARINHO] Ativado no jogador:", jogador.Name)
	
		--------------------------------------------------
		-- ACOMPANHAR EM TEMPO REAL
		--------------------------------------------------
	
		conexao = RunService.Heartbeat:Connect(function()
			if not ativo then return end
	
			local charAtual = LP.Character
			local charAlvo = alvo and alvo.Character
	
			if not charAtual or not charAlvo then
				desativar()
				return
			end
	
			local rootAtual =
				charAtual:FindFirstChild("HumanoidRootPart")
	
			local humAtual =
				charAtual:FindFirstChildOfClass("Humanoid")
	
			local headAlvo =
				charAlvo:FindFirstChild("Head")
	
			local humAlvo =
				charAlvo:FindFirstChildOfClass("Humanoid")
	
			if not rootAtual or not humAtual
				or not headAlvo or not humAlvo
				or humAtual.Health <= 0
				or humAlvo.Health <= 0 then
	
				desativar()
				return
			end
	
			local novoDestino = calcularDestino(headAlvo)
	
			if novoDestino then
				charAtual:PivotTo(novoDestino)
	
				rootAtual.AssemblyLinearVelocity = Vector3.zero
				rootAtual.AssemblyAngularVelocity = Vector3.zero
			end
		end)
	end
	
	--------------------------------------------------
	-- BOTAO
	--------------------------------------------------
	
	botao.Activated:Connect(function()
		print("[HPX CARINHO] Botao clicado!")
	
		if ativo then
			desativar()
		else
			ativar()
		end
	end)
	
	--------------------------------------------------
	-- TROCA DE JOGADOR
	--------------------------------------------------
	
	playerSelecionado:GetPropertyChangedSignal("Value"):Connect(function()
		if ativo then
			local novoAlvo = encontrarAlvo()
	
			if novoAlvo ~= alvo then
				desativar()
			end
		end
	end)
	
	--------------------------------------------------
	-- RESPAWN
	--------------------------------------------------
	
	LP.CharacterRemoving:Connect(function()
		desativar()
	end)
	
	--------------------------------------------------
	-- JOGADOR SAIU
	--------------------------------------------------
	
	Players.PlayerRemoving:Connect(function(p)
		if ativo and p == alvo then
			desativar()
		end
	end)
	
	--------------------------------------------------
	-- INICIAR
	--------------------------------------------------
	
	atualizarBotao()
	
	print("[HPX CARINHO] V2 carregado corretamente!")
	
end

